    INSERT INTO "__SCHEMA__".guide
      (guide_id, exam_id, family, title, intro, intro_en, watch_out, watch_out_en, section_count, content_version_id)
    VALUES
    ('grammar-guide', 'telc-deutsch-b1', 'grammar', 'Grammatik', NULL, NULL, '[]', '[]', 14, 'telc-deutsch-b1.grammar-guide@v1'),
    ('core-grammar', 'telc-deutsch-b1', 'core-grammar', 'Kerngrammatik', NULL, NULL, '[]', '[]', 4, 'telc-deutsch-b1.core-grammar@v1'),
    ('core-phrases', 'telc-deutsch-b1', 'core-phrases', 'Redemittel', NULL, NULL, '[]', '[]', 3, 'telc-deutsch-b1.core-phrases@v1'),
    ('gender-rules', 'telc-deutsch-b1', 'gender', 'Genus: Regeln', 'Das Genus der deutschen Nomen ist zum Teil vorhersagbar: Endungen wie -ung oder -chen und Bedeutungsgruppen wie Tage, Metalle oder junge Lebewesen geben starke Hinweise. Der Rest muss aber mit dem Artikel gelernt werden, denn keine Regel gilt ohne Ausnahme. Am besten lernst du jedes Nomen gleich mit Artikel und Plural.', 'German noun gender is partly predictable: endings such as -ung or -chen, and meaning groups such as days, metals or young creatures, are strong pointers. The rest simply has to be learned with the article, because no rule is without exception. The best habit is to learn every noun together with its article and its plural.', '["Lerne jedes neue Nomen immer mit Artikel und Plural, zum Beispiel die Wohnung, die Wohnungen.","Die Endungsregeln sind stark, aber die Bedeutung gewinnt oft: das Mädchen und das Baby sind trotz weiblicher Bedeutung neutrum.","Wörter auf -e sind meistens feminin, doch schwache Maskulina wie der Junge, der Name und der Kunde sind die große Ausnahme.","Achte besonders auf Wörter mit zwei Artikeln: der See und die See oder der Band und die Band haben verschiedene Bedeutungen.","Bei Lebensmitteln und Getränken hilft keine Regel sicher: der Kaffee, das Wasser, die Milch und das Brot musst du einzeln lernen.","Wenn du unsicher bist, schlag im Wörterbuch nach und schreibe Artikel und Plural in deine Vokabelliste."]', '["Always learn a new noun with its article and plural, for example die Wohnung, die Wohnungen.","The ending rules are strong, but meaning often wins: das Mädchen and das Baby are neuter despite referring to females.","Words in -e are mostly feminine, but weak masculines like der Junge, der Name and der Kunde are the big exception.","Pay special attention to words with two articles: der See and die See, or der Band and die Band, have different meanings.","With food and drink no rule is reliable: der Kaffee, das Wasser, die Milch and das Brot all have to be learned individually.","If you are unsure, look it up in the dictionary and write the article and the plural into your vocabulary list."]', 60, 'telc-deutsch-b1.gender-rules@v1'),
    ('cases-guide', 'telc-deutsch-b1', 'cases', 'Fälle und Artikel', 'Im Deutschen zeigt der Artikel, welche Rolle ein Nomen im Satz hat. Deshalb ändert sich der Artikel, aber das Nomen bleibt fast immer gleich. Wenn du den Fall kennst, kannst du den richtigen Artikel sicher wählen.', 'In German the article shows what role a noun plays in the sentence. That is why the article changes while the noun itself almost always stays the same. If you know the case, you can choose the right article with confidence.', '["Der Dativ Plural braucht ein -n am Nomen: mit den Kindern, nicht mit den Kinder.","Nach dem Dativ-Verb helfen steht der Dativ, nicht der Akkusativ: Ich helfe meinem Bruder.","Bei der Wechselpräposition entscheidet die Frage: Wohin? = Akkusativ, Wo? = Dativ.","Die n-Deklination wird oft vergessen: Ich sehe den Jungen, nicht den Junge.","Der Genitiv maskulin und neutrum braucht -s: das Auto meines Bruders, nicht meines Bruder.","Nach ein, kein und mein bekommt das Adjektiv im Nominativ maskulin -er: ein guter Freund, nicht ein gute Freund."]', '["The dative plural needs an -n on the noun: mit den Kindern, not mit den Kinder.","After the dative verb helfen you use the dative, not the accusative: Ich helfe meinem Bruder.","With a two-way preposition the question decides: Wohin? = accusative, Wo? = dative.","The n-declension is often forgotten: Ich sehe den Jungen, not den Junge.","The masculine and neuter genitive needs -s: das Auto meines Bruders, not meines Bruder.","After ein, kein and mein the adjective in the nominative masculine takes -er: ein guter Freund, not ein gute Freund."]', 20, 'telc-deutsch-b1.cases-guide@v1')
    INSERT INTO "__SCHEMA__".guide_section
      (guide_id, section_id, ordinal, kind, title, title_en, summary, summary_en, payload)
    VALUES
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.reflexivverben', 0, 'topic', 'Reflexivverben: sich ...', 'Reflexive verbs: sich ...', 'Reflexivverben kommen in der Prüfung ständig vor, zum Beispiel wenn Sie über Hobbys, Gefühle und Pläne sprechen, und mit ihnen klingen Ihre Sätze sofort natürlicher.', 'Reflexive verbs come up constantly in the exam — for example when you talk about hobbies, feelings and plans — and they make your sentences sound natural straight away.', '{"rule":"Bei einem Reflexivverb gehört ein kleines Wort fest zum Verb: sich freuen, sich ärgern, sich beeilen. Dieses Wort ändert sich mit der Person: ich freue mich, du freust dich, er freut sich, wir freuen uns, ihr freut euch, sie freuen sich. Bei den meisten Verben steht dieses Wort im Akkusativ (mich, dich, sich, uns, euch, sich), bei einigen aber im Dativ: Ich kann mir das gut vorstellen. Viele Reflexivverben haben außerdem eine feste Präposition, und der Kasus danach gehört einfach zum Verb: sich interessieren für + Akkusativ, sich kümmern um + Akkusativ, sich erinnern an + Akkusativ, sich ärgern über + Akkusativ, sich freuen auf + Akkusativ. Weitere häufige Verben sind sich entschuldigen bei + Dativ, sich beschweren über + Akkusativ, sich verabreden mit + Dativ, sich treffen mit + Dativ und sich fühlen.","ruleEn":"With a reflexive verb a small word belongs firmly to the verb: sich freuen, sich ärgern, sich beeilen. That word changes with the person: ich freue mich, du freust dich, er freut sich, wir freuen uns, ihr freut euch, sie freuen sich. With most verbs this word is in the accusative (mich, dich, sich, uns, euch, sich), but with some it is in the dative: Ich kann mir das gut vorstellen. Many reflexive verbs also take a fixed preposition, and the case after it simply belongs to the verb: sich interessieren für + accusative, sich kümmern um + accusative, sich erinnern an + accusative, sich ärgern über + accusative, sich freuen auf + accusative. Other common verbs are sich entschuldigen bei + dative, sich beschweren über + accusative, sich verabreden mit + dative, sich treffen mit + dative and sich fühlen.","pattern":"sich + Verb (+ Präposition + Kasus)","patternEn":"sich + verb (+ preposition + case)","examples":[{"de":"Ich interessiere mich für Musik und gehe jeden Samstag ins Konzert.","en":"I am interested in music and go to a concert every Saturday.","note":"sich interessieren für + Akkusativ"},{"de":"Wir freuen uns schon sehr auf den Urlaub in Italien.","en":"We are already very much looking forward to the holiday in Italy.","note":"sich freuen auf + Akkusativ (Zukunft)"},{"de":"Kannst du dich bitte um die Getränke kümmern?","en":"Could you please take care of the drinks?","note":"sich kümmern um + Akkusativ"},{"de":"Ich kann mich nicht mehr an seinen Namen erinnern.","en":"I can no longer remember his name.","note":"sich erinnern an + Akkusativ"},{"de":"Wir müssen uns beeilen, sonst verpassen wir den Zug.","en":"We have to hurry, otherwise we will miss the train.","note":"sich beeilen steht ohne Präposition"},{"de":"Ich kann mir gut vorstellen, in Deutschland zu arbeiten.","en":"I can well imagine working in Germany.","note":"sich vorstellen + Dativ (mir) + zu + Infinitiv"}],"table":{"headers":["Person","Akkusativ","Dativ"],"rows":[["ich","mich","mir"],["du","dich","dir"],["er / sie / es","sich","sich"],["wir","uns","uns"],["ihr","euch","euch"],["sie / Sie","sich","sich"]],"headersEn":["person","accusative","dative"],"firstColumnEn":["I","you","he / she / it","we","you (plural)","they / you (formal)"]},"traps":["Falsch: Ich interessiere mich über Musik. – Richtig: Ich interessiere mich für Musik.","Falsch: Ich freue mich über den Urlaub nächste Woche. – Richtig: Ich freue mich auf den Urlaub nächste Woche, denn es geht um die Zukunft.","Falsch: Ich kann mich gut vorstellen, in Deutschland zu arbeiten. – Richtig: Ich kann mir gut vorstellen, in Deutschland zu arbeiten.","Falsch: Ich interessiere mich für Musik nicht. – Richtig: Ich interessiere mich nicht für Musik."],"trapsEn":["Wrong: Ich interessiere mich über Musik. – Right: Ich interessiere mich für Musik.","Wrong: Ich freue mich über den Urlaub nächste Woche. – Right: Ich freue mich auf den Urlaub nächste Woche, because it is about the future.","Wrong: Ich kann mich gut vorstellen, in Deutschland zu arbeiten. – Right: Ich kann mir gut vorstellen, in Deutschland zu arbeiten.","Wrong: Ich interessiere mich für Musik nicht. – Right: Ich interessiere mich nicht für Musik."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.um-zu-infinitiv', 1, 'topic', 'um ... zu + Infinitiv', 'um ... zu + infinitive', 'Mit um ... zu können Sie in der mündlichen Prüfung Ziele und Gründe kurz und sicher nennen, ohne einen langen Nebensatz zu bauen.', 'With um ... zu you can name goals and reasons briefly and confidently in the oral exam, without building a long subordinate clause.', '{"rule":"Mit um ... zu + Infinitiv sagen Sie, warum jemand etwas macht, also welches Ziel er hat. Die beiden Teile stehen weit auseinander: um steht nach dem Komma am Anfang, zu + Infinitiv steht ganz am Ende. Das geht nur, wenn beide Teile dieselbe Person haben. Wenn die Personen verschieden sind, nehmen Sie damit und einen Nebensatz mit dem Verb am Ende. Bei trennbaren Verben schiebt sich zu zwischen Vorsilbe und Verb: einkaufen wird einzukaufen, anrufen wird anzurufen.","ruleEn":"With um ... zu + infinitive you say why someone does something, that is, what their goal is. The two parts stand far apart: um comes after the comma at the start, zu + infinitive comes right at the end. This only works when both parts have the same person. If the people are different, you use damit and a subordinate clause with the verb at the end. With separable verbs zu slips between the prefix and the verb: einkaufen becomes einzukaufen, anrufen becomes anzurufen.","pattern":"Hauptsatz, um ... zu + Infinitiv","patternEn":"main clause, um ... zu + infinitive","examples":[{"de":"Ich stehe jeden Morgen früh auf, um vor der Arbeit Deutsch zu lernen.","en":"I get up early every morning in order to study German before work.","note":"gleiche Person im Haupt- und Nebensatz"},{"de":"Wir fahren am Samstag in die Stadt, um neue Schuhe zu kaufen.","en":"On Saturday we are going into town to buy new shoes.","note":"zu + Infinitiv steht am Satzende"},{"de":"Sie hat den Job gewechselt, um mehr Geld zu verdienen.","en":"She changed jobs in order to earn more money.","note":"Perfekt im Hauptsatz, danach um ... zu + Infinitiv"},{"de":"Ich habe heute keine Zeit, um noch einzukaufen.","en":"I have no time today to go shopping.","note":"trennbares Verb: ein|kaufen wird einzukaufen"},{"de":"Er hat mir geschrieben, um sich zu entschuldigen.","en":"He wrote to me in order to apologise.","note":"Reflexivverb: sich entschuldigen wird sich zu entschuldigen"},{"de":"Ich spreche langsam, damit du mich besser verstehst.","en":"I speak slowly so that you understand me better.","note":"verschiedene Personen: damit + Verb am Ende"}],"table":{"headers":["Gleiche Person: um ... zu","Verschiedene Personen: damit"],"rows":[["Ich lerne jeden Tag Vokabeln, um die Prüfung zu bestehen.","Ich lerne jeden Tag Vokabeln, damit mein Bruder die Prüfung besteht."],["Wir fahren früh los, um den Stau zu vermeiden.","Wir fahren früh los, damit die Kinder nicht so lange warten müssen."]],"headersEn":["same person: um ... zu","different people: damit"]},"traps":["Falsch: Ich lerne Deutsch, um in Deutschland arbeiten. – Richtig: Ich lerne Deutsch, um in Deutschland zu arbeiten.","Falsch: Ich spreche langsam, um mein Lehrer mich versteht. – Richtig: Ich spreche langsam, damit mein Lehrer mich versteht.","Falsch: Ich gehe in den Supermarkt, um einkaufen zu. – Richtig: Ich gehe in den Supermarkt, um einzukaufen.","Falsch: Um die Prüfung zu bestehen, ich lerne jeden Tag. – Richtig: Um die Prüfung zu bestehen, lerne ich jeden Tag."],"trapsEn":["Wrong: Ich lerne Deutsch, um in Deutschland arbeiten. – Right: Ich lerne Deutsch, um in Deutschland zu arbeiten.","Wrong: Ich spreche langsam, um mein Lehrer mich versteht. – Right: Ich spreche langsam, damit mein Lehrer mich versteht.","Wrong: Ich gehe in den Supermarkt, um einkaufen zu. – Right: Ich gehe in den Supermarkt, um einzukaufen.","Wrong: Um die Prüfung zu bestehen, ich lerne jeden Tag. – Right: Um die Prüfung zu bestehen, lerne ich jeden Tag."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.infinitiv-mit-zu', 2, 'topic', 'Infinitiv mit zu', 'Infinitive with zu', 'Viele Verben und Ausdrücke, die Sie in der Prüfung oft brauchen, verlangen zu + Infinitiv, und wer das zu vergisst, macht einen sehr typischen Fehler.', 'Many verbs and expressions that you often need in the exam require zu + infinitive, and forgetting that zu is a very typical mistake.', '{"rule":"Nach bestimmten Verben steht zu + Infinitiv: vorhaben, versuchen, vergessen, anfangen, aufhören und hoffen. Auch feste Ausdrücke wie Lust haben, Zeit haben, es ist wichtig und es ist schwierig nehmen zu + Infinitiv. Der Infinitiv steht am Ende des Satzes, und bei trennbaren Verben steht zu in der Mitte: einzukaufen, anzurufen, aufzustehen. Nach Modalverben wie können, müssen oder wollen steht dagegen kein zu, dort genügt der Infinitiv am Satzende. Das Verb nach zu verändert sich nie, egal ob ich, du oder wir im Satz steht.","ruleEn":"After certain verbs you use zu + infinitive: vorhaben, versuchen, vergessen, anfangen, aufhören and hoffen. Fixed expressions such as Lust haben, Zeit haben, es ist wichtig and es ist schwierig also take zu + infinitive. The infinitive stands at the end of the sentence, and with separable verbs zu goes in the middle: einzukaufen, anzurufen, aufzustehen. After modal verbs such as können, müssen or wollen there is no zu — the bare infinitive at the end of the sentence is enough. The verb after zu never changes, whether the sentence has ich, du or wir.","pattern":"Verb / Ausdruck + zu + Infinitiv (am Satzende)","patternEn":"verb / expression + zu + infinitive (at the end of the sentence)","examples":[{"de":"Ich habe vor, im Sommer einen Deutschkurs zu machen.","en":"I plan to take a German course in the summer.","note":"vorhaben + zu + Infinitiv"},{"de":"Er versucht, jeden Tag zwanzig neue Wörter zu lernen.","en":"He tries to learn twenty new words every day.","note":"versuchen + zu + Infinitiv"},{"de":"Hast du Lust, am Wochenende mit uns ins Kino zu gehen?","en":"Do you feel like going to the cinema with us at the weekend?","note":"Lust haben + zu + Infinitiv"},{"de":"Ich habe vergessen, die Rechnung zu bezahlen.","en":"I forgot to pay the bill.","note":"vergessen + zu + Infinitiv"},{"de":"Es ist wichtig, jeden Tag ein bisschen zu üben.","en":"It is important to practise a little every day.","note":"es ist wichtig + zu + Infinitiv"},{"de":"Wir haben aufgehört, jeden Abend fernzusehen.","en":"We stopped watching television every evening.","note":"trennbares Verb: fern|sehen wird fernzusehen"}],"traps":["Falsch: Ich versuche, jeden Tag Deutsch lernen. – Richtig: Ich versuche, jeden Tag Deutsch zu lernen.","Falsch: Ich muss heute zu arbeiten. – Richtig: Ich muss heute arbeiten, denn nach Modalverben steht kein zu.","Falsch: Ich habe vor, einzukaufen im Supermarkt. – Richtig: Ich habe vor, im Supermarkt einzukaufen.","Falsch: Es ist wichtig, dass jeden Tag zu üben. – Richtig: Es ist wichtig, jeden Tag zu üben."],"trapsEn":["Wrong: Ich versuche, jeden Tag Deutsch lernen. – Right: Ich versuche, jeden Tag Deutsch zu lernen.","Wrong: Ich muss heute zu arbeiten. – Right: Ich muss heute arbeiten, because there is no zu after modal verbs.","Wrong: Ich habe vor, einzukaufen im Supermarkt. – Right: Ich habe vor, im Supermarkt einzukaufen.","Wrong: Es ist wichtig, dass jeden Tag zu üben. – Right: Es ist wichtig, jeden Tag zu üben."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.nebensatz-wortstellung', 3, 'topic', 'Nebensätze: das Verb ans Ende', 'Subordinate clauses: the verb goes to the end', 'In fast jeder Aufgabe verbinden Sie zwei Sätze, und in der Prüfung fällt sofort auf, wenn das Verb im Nebensatz nicht am Ende steht.', 'In almost every task you join two sentences, and in the exam it is immediately obvious when the verb in a subordinate clause is not at the end.', '{"rule":"Ein Nebensatz beginnt mit einem Wort wie weil, dass, obwohl, wenn, als, damit, ob, während, bevor, nachdem oder seitdem. In diesem Nebensatz steht das konjugierte Verb ganz am Ende. Hauptsatz und Nebensatz trennt man mit einem Komma. Steht der Nebensatz zuerst, beginnt der Hauptsatz direkt nach dem Komma mit dem Verb. Bei trennbaren Verben steht im Nebensatz das ganze Verb zusammen am Ende.","ruleEn":"A subordinate clause begins with a word such as weil, dass, obwohl, wenn, als, damit, ob, während, bevor, nachdem or seitdem. In this subordinate clause the conjugated verb stands right at the end. Main clause and subordinate clause are separated by a comma. If the subordinate clause comes first, the main clause begins with the verb directly after the comma. With separable verbs the whole verb stands together at the end of the subordinate clause.","pattern":"..., weil / dass / obwohl / wenn + Subjekt + ... + Verb (am Ende)","patternEn":"..., weil / dass / obwohl / wenn + subject + ... + verb (at the end)","examples":[{"de":"Ich komme heute später, weil ich noch einen Termin beim Arzt habe.","en":"I will be a bit later today because I still have a doctor’s appointment.","note":"weil + konjugiertes Verb am Ende"},{"de":"Er hat mir gesagt, dass er nächste Woche umzieht.","en":"He told me that he is moving next week.","note":"dass + konjugiertes Verb am Ende"},{"de":"Obwohl es stark geregnet hat, sind wir spazieren gegangen.","en":"Although it rained heavily, we went for a walk.","note":"Nebensatz zuerst, dann beginnt der Hauptsatz mit dem Verb"},{"de":"Wenn ich Zeit habe, rufe ich dich heute Abend an.","en":"If I have time, I will call you this evening.","note":"Hauptsatz mit trennbarem Verb: rufe ... an"},{"de":"Weißt du schon, ob der Kurs am Montag anfängt?","en":"Do you already know whether the course starts on Monday?","note":"indirekte Frage mit ob, Verb am Ende"},{"de":"Nachdem ich gefrühstückt hatte, bin ich zur Arbeit gefahren.","en":"After I had had breakfast, I drove to work.","note":"nachdem + Plusquamperfekt, danach der Hauptsatz"}],"traps":["Falsch: Ich komme später, weil ich habe noch einen Termin. – Richtig: Ich komme später, weil ich noch einen Termin habe.","Falsch: Obwohl es hat geregnet, sind wir spazieren gegangen. – Richtig: Obwohl es geregnet hat, sind wir spazieren gegangen.","Falsch: Wenn ich Zeit habe, ich rufe dich an. – Richtig: Wenn ich Zeit habe, rufe ich dich an.","Falsch: Ich komme nicht, weil ich anfange um acht Uhr. – Richtig: Ich komme nicht, weil ich um acht Uhr anfange."],"trapsEn":["Wrong: Ich komme später, weil ich habe noch einen Termin. – Right: Ich komme später, weil ich noch einen Termin habe.","Wrong: Obwohl es hat geregnet, sind wir spazieren gegangen. – Right: Obwohl es geregnet hat, sind wir spazieren gegangen.","Wrong: Wenn ich Zeit habe, ich rufe dich an. – Right: Wenn ich Zeit habe, rufe ich dich an.","Wrong: Ich komme nicht, weil ich anfange um acht Uhr. – Right: Ich komme nicht, weil ich um acht Uhr anfange."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.wechselpraepositionen', 4, 'topic', 'Wechselpräpositionen: wo? / wohin?', 'Two-way prepositions: wo? / wohin?', 'Diese neun Präpositionen brauchen Sie für Wegbeschreibungen, für die Bildbeschreibung in der Prüfung und für jede Geschichte in der Vergangenheit.', 'You need these nine prepositions for giving directions, for describing a picture in the exam, and for any story in the past.', '{"rule":"Zu den Wechselpräpositionen gehören an, auf, in, über, unter, vor, hinter, neben und zwischen. Wenn sich etwas bewegt oder wohin kommt, steht danach der Akkusativ: Ich gehe in die Küche. Wenn etwas nur an einem Ort liegt oder steht, steht danach der Dativ: Ich bin in der Küche. Die Frage hilft immer: wohin? ergibt Akkusativ, wo? ergibt Dativ. Es gibt feste Verbpaare, die man zusammen lernen sollte: legen und liegen, stellen und stehen, hängen und hängen, setzen und sitzen, wobei das Akkusativ-Verb die Bewegung und das Dativ-Verb die Position zeigt.","ruleEn":"The two-way prepositions are an, auf, in, über, unter, vor, hinter, neben and zwischen. If something moves or is going somewhere, the accusative follows: Ich gehe in die Küche. If something is simply located somewhere, the dative follows: Ich bin in der Küche. The question always helps: wohin? gives the accusative, wo? gives the dative. There are fixed verb pairs worth learning together: legen and liegen, stellen and stehen, hängen and hängen, setzen and sitzen, where the accusative verb shows movement and the dative verb shows position.","pattern":"wohin? + Akkusativ | wo? + Dativ","patternEn":"wohin? + accusative | wo? + dative","examples":[{"de":"Ich hänge die Jacke in den Schrank.","en":"I hang the jacket in the wardrobe.","note":"wohin? in + Akkusativ"},{"de":"Die Jacke hängt im Schrank.","en":"The jacket is hanging in the wardrobe.","note":"wo? in + Dativ (im = in dem)"},{"de":"Bitte lege die Zeitung auf den Küchentisch.","en":"Please put the newspaper on the kitchen table.","note":"legen + auf + Akkusativ (Bewegung)"},{"de":"Die Zeitung liegt schon auf dem Küchentisch.","en":"The newspaper is already lying on the kitchen table.","note":"liegen + auf + Dativ (Position)"},{"de":"Wir treffen uns um sieben Uhr vor dem Kino.","en":"We are meeting in front of the cinema at seven o’clock.","note":"wo? vor + Dativ"},{"de":"Stell die Flaschen bitte in den Kühlschrank.","en":"Please put the bottles in the fridge.","note":"stellen + in + Akkusativ"}],"table":{"headers":["wohin? (Akkusativ)","wo? (Dativ)"],"rows":[["Ich hänge das Bild an die Wand.","Das Bild hängt an der Wand."],["Er legt das Buch auf den Tisch.","Das Buch liegt auf dem Tisch."],["Wir gehen in die Stadt.","Wir sind in der Stadt."],["Sie stellt die Vase neben das Fenster.","Die Vase steht neben dem Fenster."],["Ich setze mich zwischen die beiden Kinder.","Ich sitze zwischen den beiden Kindern."]],"headersEn":["wohin? (accusative)","wo? (dative)"]},"traps":["Falsch: Ich gehe in der Küche. – Richtig: Ich gehe in die Küche, denn auf die Frage wohin? folgt der Akkusativ.","Falsch: Das Buch liegt auf den Tisch. – Richtig: Das Buch liegt auf dem Tisch.","Falsch: Ich lege mich auf dem Sofa. – Richtig: Ich lege mich auf das Sofa.","Falsch: Er steht vor die Tür. – Richtig: Er steht vor der Tür."],"trapsEn":["Wrong: Ich gehe in der Küche. – Right: Ich gehe in die Küche, because the question wohin? takes the accusative.","Wrong: Das Buch liegt auf den Tisch. – Right: Das Buch liegt auf dem Tisch.","Wrong: Ich lege mich auf dem Sofa. – Right: Ich lege mich auf das Sofa.","Wrong: Er steht vor die Tür. – Right: Er steht vor der Tür."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.praepositionen-kasus', 5, 'topic', 'Präpositionen und ihr Kasus', 'Prepositions and their case', 'Der Kasus nach der Präposition ist ein Lieblingsthema der Prüfer, und mit einer kurzen Liste können Sie hier viele Punkte sicher machen.', 'The case after a preposition is a favourite topic with examiners, and with a short list you can secure a lot of marks here.', '{"rule":"Manche Präpositionen haben immer den Dativ: aus, bei, mit, nach, seit, von, zu und gegenüber. Andere haben immer den Akkusativ: durch, für, gegen, ohne, um, bis und entlang. Bei entlang steht das Wort meistens nach dem Nomen: die Straße entlang. Viele Präpositionen verschmelzen mit dem Artikel zu einem kurzen Wort: zu dem wird zum, zu der wird zur, bei dem wird beim, von dem wird vom, in dem wird im, an dem wird am, an das wird ans, in das wird ins. Diese kurzen Formen benutzt man im Alltag fast immer.","ruleEn":"Some prepositions always take the dative: aus, bei, mit, nach, seit, von, zu and gegenüber. Others always take the accusative: durch, für, gegen, ohne, um, bis and entlang. With entlang the word usually comes after the noun: die Straße entlang. Many prepositions merge with the article into a short word: zu dem becomes zum, zu der becomes zur, bei dem becomes beim, von dem becomes vom, in dem becomes im, an dem becomes am, an das becomes ans, in das becomes ins. These short forms are used almost always in everyday speech.","pattern":"Dativ: aus, bei, mit, nach, seit, von, zu | Akkusativ: durch, für, gegen, ohne, um, bis","patternEn":"dative: aus, bei, mit, nach, seit, von, zu | accusative: durch, für, gegen, ohne, um, bis","examples":[{"de":"Ich fahre jeden Tag mit dem Fahrrad zur Arbeit.","en":"I cycle to work every day.","note":"mit + Dativ, zur = zu der"},{"de":"Nach dem Unterricht gehe ich noch kurz zum Supermarkt.","en":"After the lesson I will quickly go to the supermarket.","note":"nach + Dativ, zum = zu dem"},{"de":"Seit drei Jahren wohne ich bei meinen Eltern.","en":"I have been living with my parents for three years.","note":"seit + Dativ, bei + Dativ"},{"de":"Wir gehen ohne unseren Lehrer durch den Park.","en":"We are walking through the park without our teacher.","note":"ohne + Akkusativ, durch + Akkusativ"},{"de":"Das Geschenk ist für meine Schwester und nicht für mich.","en":"The present is for my sister and not for me.","note":"für + Akkusativ"},{"de":"Wir sitzen seit einer Stunde im Café gegenüber dem Bahnhof.","en":"We have been sitting in the café opposite the station for an hour.","note":"gegenüber + Dativ"}],"table":{"headers":["Dativ","Akkusativ"],"rows":[["aus dem Haus","durch den Park"],["bei meiner Tante","für meinen Bruder"],["mit dem Bus","gegen die Regeln"],["nach der Arbeit","ohne meinen Schlüssel"],["seit einem Jahr","um den See"],["von der Arbeit / zum Arzt / zur Schule","bis nächsten Montag / die Straße entlang"]],"headersEn":["dative","accusative"]},"traps":["Falsch: Ich fahre mit den Bus. – Richtig: Ich fahre mit dem Bus.","Falsch: Das Geschenk ist für meinem Bruder. – Richtig: Das Geschenk ist für meinen Bruder.","Falsch: Seit drei Jahre lerne ich Deutsch. – Richtig: Seit drei Jahren lerne ich Deutsch.","Falsch: Nach der Arbeit ich gehe zum Sport. – Richtig: Nach der Arbeit gehe ich zum Sport."],"trapsEn":["Wrong: Ich fahre mit den Bus. – Right: Ich fahre mit dem Bus.","Wrong: Das Geschenk ist für meinem Bruder. – Right: Das Geschenk ist für meinen Bruder.","Wrong: Seit drei Jahre lerne ich Deutsch. – Right: Seit drei Jahren lerne ich Deutsch.","Wrong: Nach der Arbeit ich gehe zum Sport. – Right: Nach der Arbeit gehe ich zum Sport."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.relativsaetze', 6, 'topic', 'Relativsätze', 'Relative clauses', 'Relativsätze machen Ihre Sätze in der Prüfung reicher und zeigen, dass Sie Personen und Dinge genauer beschreiben können.', 'Relative clauses make your sentences in the exam richer and show that you can describe people and things more precisely.', '{"rule":"Ein Relativsatz beschreibt ein Nomen aus dem Hauptsatz genauer und steht direkt nach diesem Nomen. Das Relativpronomen richtet sich in Geschlecht und Zahl nach dem Nomen: der Mann, der ...; die Frau, die ...; das Kind, das ...; die Freunde, die .... Den Kasus bestimmt aber die Rolle im Relativsatz, zum Beispiel: Ich kenne den Mann, den alle mögen. Im Relativsatz steht das konjugierte Verb am Ende. Mit Präposition steht die Präposition vor dem Relativpronomen: der Kollege, mit dem ich arbeite.","ruleEn":"A relative clause describes a noun from the main clause more precisely and stands directly after that noun. The relative pronoun matches the noun in gender and number: der Mann, der ...; die Frau, die ...; das Kind, das ...; die Freunde, die .... The case, however, is decided by the role in the relative clause, for example: Ich kenne den Mann, den alle mögen. In the relative clause the conjugated verb stands at the end. With a preposition the preposition comes before the relative pronoun: der Kollege, mit dem ich arbeite.","pattern":"Nomen + , + Relativpronomen + ... + Verb (am Ende)","patternEn":"noun + , + relative pronoun + ... + verb (at the end)","examples":[{"de":"Das ist der Kollege, der mir immer hilft.","en":"That is the colleague who always helps me.","note":"der = Nominativ maskulin"},{"de":"Die Wohnung, die wir gemietet haben, ist sehr hell.","en":"The flat that we rented is very bright.","note":"die = Akkusativ feminin"},{"de":"Der Mann, dem ich geholfen habe, war sehr freundlich.","en":"The man whom I helped was very friendly.","note":"dem = Dativ maskulin"},{"de":"Die Nachbarn, mit denen wir oft grillen, sind im Urlaub.","en":"The neighbours with whom we often have a barbecue are on holiday.","note":"Präposition + denen = Dativ Plural"},{"de":"Das ist die Firma, bei der mein Vater arbeitet.","en":"That is the company where my father works.","note":"bei + der = Dativ feminin"},{"de":"Kennst du die Frau, deren Sohn bei uns in der Klasse ist?","en":"Do you know the woman whose son is in our class?","note":"deren = Genitiv feminin"}],"traps":["Falsch: Das ist der Mann, den mir geholfen hat. – Richtig: Das ist der Mann, der mir geholfen hat.","Falsch: Die Frau, ich gestern gesehen habe, wohnt hier. – Richtig: Die Frau, die ich gestern gesehen habe, wohnt hier.","Falsch: Der Kollege, mit der ich arbeite, ist krank. – Richtig: Der Kollege, mit dem ich arbeite, ist krank.","Falsch: Kennst du die Frau, dessen Sohn in unserer Klasse ist? – Richtig: Kennst du die Frau, deren Sohn in unserer Klasse ist?"],"trapsEn":["Wrong: Das ist der Mann, den mir geholfen hat. – Right: Das ist der Mann, der mir geholfen hat.","Wrong: Die Frau, ich gestern gesehen habe, wohnt hier. – Right: Die Frau, die ich gestern gesehen habe, wohnt hier.","Wrong: Der Kollege, mit der ich arbeite, ist krank. – Right: Der Kollege, mit dem ich arbeite, ist krank.","Wrong: Kennst du die Frau, dessen Sohn in unserer Klasse ist? – Right: Kennst du die Frau, deren Sohn in unserer Klasse ist?"]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.perfekt-praeteritum', 7, 'topic', 'Perfekt und Präteritum', 'Perfect and preterite', 'Die Vergangenheit kommt in der mündlichen Prüfung und im Brief ständig vor, und ein falsches Hilfsverb fällt sofort auf.', 'The past tense comes up constantly in the oral exam and in letters, and a wrong auxiliary verb is immediately noticeable.', '{"rule":"Für die Vergangenheit, über die man spricht, nimmt man das Perfekt: haben oder sein plus Partizip II. Die meisten Verben nehmen haben: Ich habe gearbeitet. Sein nimmt man bei Verben der Bewegung von einem Ort zu einem anderen und bei der Veränderung eines Zustands: Ich bin nach Berlin gefahren, ich bin eingeschlafen. Das Präteritum benutzt man fast nur bei sein, haben, werden und den Modalverben: ich war, ich hatte, ich wurde, ich konnte. Regelmäßige Verben bilden das Partizip II mit ge ... t (arbeiten wird gearbeitet), unregelmäßige Formen muss man lernen: gegangen, gegessen, genommen.","ruleEn":"For the past that you talk about, you use the perfect: haben or sein plus the past participle. Most verbs take haben: Ich habe gearbeitet. You use sein with verbs of movement from one place to another and with a change of state: Ich bin nach Berlin gefahren, ich bin eingeschlafen. The preterite is used almost only with sein, haben, werden and the modal verbs: ich war, ich hatte, ich wurde, ich konnte. Regular verbs form the past participle with ge ... t (arbeiten becomes gearbeitet); irregular forms have to be learned: gegangen, gegessen, genommen.","pattern":"haben / sein + Partizip II (am Satzende)","patternEn":"haben / sein + past participle (at the end of the sentence)","examples":[{"de":"Gestern habe ich drei Stunden Deutsch gelernt.","en":"Yesterday I studied German for three hours.","note":"haben + Partizip II"},{"de":"Letztes Jahr sind wir nach Österreich gefahren.","en":"Last year we went to Austria.","note":"Bewegung: sein + gefahren"},{"de":"Sie ist heute Morgen um sieben Uhr aufgestanden.","en":"She got up at seven o’clock this morning.","note":"trennbares Verb: aufgestanden"},{"de":"Als Kind hatte ich einen Hund und zwei Katzen.","en":"As a child I had a dog and two cats.","note":"Präteritum von haben"},{"de":"Wir mussten gestern lange auf den Bus warten.","en":"Yesterday we had to wait a long time for the bus.","note":"Modalverben stehen im Präteritum: mussten"},{"de":"Bist du schon einmal in Deutschland gewesen?","en":"Have you ever been to Germany?","note":"Perfekt von sein: sein + gewesen"}],"table":{"headers":["Infinitiv","Partizip II","Hilfsverb"],"rows":[["gehen","gegangen","sein"],["fahren","gefahren","sein"],["kommen","gekommen","sein"],["bleiben","geblieben","sein"],["aufstehen","aufgestanden","sein"],["essen","gegessen","haben"],["trinken","getrunken","haben"],["nehmen","genommen","haben"],["schreiben","geschrieben","haben"],["sprechen","gesprochen","haben"]],"headersEn":["infinitive","past participle","auxiliary"]},"traps":["Falsch: Ich habe nach Berlin gefahren. – Richtig: Ich bin nach Berlin gefahren.","Falsch: Ich bin drei Stunden Deutsch gelernt. – Richtig: Ich habe drei Stunden Deutsch gelernt.","Falsch: Gestern ich habe viel gearbeitet. – Richtig: Gestern habe ich viel gearbeitet.","Falsch: Ich bin in die Stadt gegeht. – Richtig: Ich bin in die Stadt gegangen."],"trapsEn":["Wrong: Ich habe nach Berlin gefahren. – Right: Ich bin nach Berlin gefahren.","Wrong: Ich bin drei Stunden Deutsch gelernt. – Right: Ich habe drei Stunden Deutsch gelernt.","Wrong: Gestern ich habe viel gearbeitet. – Right: Gestern habe ich viel gearbeitet.","Wrong: Ich bin in die Stadt gegeht. – Right: Ich bin in die Stadt gegangen."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.konjunktiv2', 8, 'topic', 'Konjunktiv II: höflich und irreal', 'Konjunktiv II: polite and unreal', 'Höfliche Bitten und irreale Sätze mit wenn ... hätte sind im Brief und in der mündlichen Prüfung der sicherste Weg zu einem guten Eindruck.', 'Polite requests and unreal sentences with wenn ... hätte are the surest way to make a good impression in a letter and in the oral exam.', '{"rule":"Mit dem Konjunktiv II sagt man etwas höflich oder etwas, das nicht wirklich so ist. Die wichtigsten Formen sind hätte, wäre, würde, könnte, müsste und dürfte. In Briefen und Bitten benutzt man sie für Höflichkeit, zum Beispiel: Ich hätte eine Frage, könnten Sie mir bitte bis Freitag antworten. Für irreale Bedingungen nimmt man wenn + Konjunktiv II und im zweiten Teil oft würde + Infinitiv: Wenn ich mehr Zeit hätte, würde ich jeden Tag schwimmen. Die Vergangenheit bildet man mit hätte oder wäre plus Partizip II: Ich hätte dir gerne geholfen, aber ich hatte keine Zeit.","ruleEn":"With the Konjunktiv II you say something politely, or something that is not really the case. The most important forms are hätte, wäre, würde, könnte, müsste and dürfte. In letters and requests they are used for politeness, for example: Ich hätte eine Frage, könnten Sie mir bitte bis Freitag antworten. For unreal conditions you use wenn + Konjunktiv II and often würde + infinitive in the second part: Wenn ich mehr Zeit hätte, würde ich jeden Tag schwimmen. The past is formed with hätte or wäre plus the past participle: Ich hätte dir gerne geholfen, aber ich hatte keine Zeit.","pattern":"hätte / wäre / würde / könnte + Infinitiv","patternEn":"hätte / wäre / würde / könnte + infinitive","examples":[{"de":"Könnten Sie mir bitte bis Freitag antworten?","en":"Could you please reply to me by Friday?","note":"höfliche Bitte mit könnten"},{"de":"Ich hätte eine Frage zu Ihrer Anzeige in der Zeitung.","en":"I would have a question about your advert in the newspaper.","note":"höflich mit hätte"},{"de":"Wenn ich mehr Zeit hätte, würde ich einen Sprachkurs machen.","en":"If I had more time, I would take a language course.","note":"irreale Bedingung: wenn + hätte, würde + Infinitiv"},{"de":"An deiner Stelle wäre ich vorsichtiger.","en":"In your place I would be more careful.","note":"wäre = Konjunktiv II von sein"},{"de":"Es wäre schön, wenn wir uns nächste Woche treffen könnten.","en":"It would be nice if we could meet next week.","note":"könnten steht am Ende des Nebensatzes"},{"de":"Ich hätte dir gerne geholfen, aber ich war im Urlaub.","en":"I would gladly have helped you, but I was on holiday.","note":"Vergangenheit: hätte + Partizip II"}],"traps":["Falsch: Wenn ich Zeit hätte, ich würde mehr lesen. – Richtig: Wenn ich Zeit hätte, würde ich mehr lesen.","Falsch: Ich würde haben eine Frage. – Richtig: Ich hätte eine Frage.","Falsch: Ich würde dir gerne geholfen. – Richtig: Ich hätte dir gerne geholfen.","Falsch: Es wäre schön, wenn wir uns treffen würden können. – Richtig: Es wäre schön, wenn wir uns treffen könnten."],"trapsEn":["Wrong: Wenn ich Zeit hätte, ich würde mehr lesen. – Right: Wenn ich Zeit hätte, würde ich mehr lesen.","Wrong: Ich würde haben eine Frage. – Right: Ich hätte eine Frage.","Wrong: Ich würde dir gerne geholfen. – Right: Ich hätte dir gerne geholfen.","Wrong: Es wäre schön, wenn wir uns treffen würden können. – Right: Es wäre schön, wenn wir uns treffen könnten."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.adjektivendungen', 9, 'topic', 'Adjektivendungen', 'Adjective endings', 'Adjektivendungen wirken kompliziert, aber mit einer kleinen Tabelle und drei Fällen schreiben Sie in der Prüfung fast automatisch richtig.', 'Adjective endings look complicated, but with a small table and three cases you will write them correctly almost automatically in the exam.', '{"rule":"Die Endung des Adjektivs hängt vom Artikel, vom Kasus und vom Nomen ab. Nach der, die und das ist die Endung meist -e oder -en: der neue Job, die neue Wohnung, den neuen Job. Nach ein und eine ist sie meist -er, -es oder -en: ein neuer Job, ein neues Auto, eine neue Wohnung. Ohne Artikel zeigt das Adjektiv den Kasus selbst: guter Wein, frisches Brot, kalte Milch, neue Ideen. Im Dativ steht fast immer -en (mit dem neuen Auto, mit einer neuen Kollegin), und im Plural steht nach der, die, das und nach ein-Wörtern im Nominativ und Akkusativ immer -en: die neuen Nachbarn.","ruleEn":"The adjective ending depends on the article, the case and the noun. After der, die and das the ending is usually -e or -en: der neue Job, die neue Wohnung, den neuen Job. After ein and eine it is usually -er, -es or -en: ein neuer Job, ein neues Auto, eine neue Wohnung. With no article the adjective shows the case itself: guter Wein, frisches Brot, kalte Milch, neue Ideen. In the dative it is almost always -en (mit dem neuen Auto, mit einer neuen Kollegin), and in the plural after der, die, das and after ein-words in the nominative and accusative it is always -en: die neuen Nachbarn.","pattern":"Artikel + Adjektiv + Endung + Nomen","patternEn":"article + adjective + ending + noun","examples":[{"de":"Ich habe mir einen neuen Job gesucht.","en":"I looked for a new job.","note":"Akkusativ maskulin nach ein-Wort: -en"},{"de":"Das ist ein wirklich interessantes Buch.","en":"That is a really interesting book.","note":"Nominativ neutrum nach ein: -es"},{"de":"Wir wohnen in einer kleinen Wohnung im Zentrum.","en":"We live in a small flat in the centre.","note":"Dativ feminin nach ein-Wort: -en"},{"de":"Die neuen Nachbarn sind sehr freundlich.","en":"The new neighbours are very friendly.","note":"Plural nach die: -en"},{"de":"Mit kaltem Wasser kann ich nicht duschen.","en":"I cannot shower with cold water.","note":"ohne Artikel, Dativ neutrum: -em"},{"de":"Ich trinke am liebsten starken Kaffee.","en":"I prefer drinking strong coffee.","note":"ohne Artikel, Akkusativ maskulin: -en"}],"table":{"headers":["Kasus","maskulin","neutrum","feminin","Plural"],"rows":[["Nominativ nach der / die / das","der neue Job","das neue Auto","die neue Wohnung","die neuen Ideen"],["Akkusativ nach der / die / das","den neuen Job","das neue Auto","die neue Wohnung","die neuen Ideen"],["Dativ nach der / die / das","dem neuen Job","dem neuen Auto","der neuen Wohnung","den neuen Ideen"],["Nominativ nach ein / eine","ein neuer Job","ein neues Auto","eine neue Wohnung","meine neuen Ideen"],["Akkusativ nach ein / eine","einen neuen Job","ein neues Auto","eine neue Wohnung","meine neuen Ideen"],["Dativ nach ein / eine","einem neuen Job","einem neuen Auto","einer neuen Wohnung","meinen neuen Ideen"],["Nominativ ohne Artikel","guter Wein","frisches Brot","kalte Milch","neue Ideen"],["Akkusativ ohne Artikel","guten Wein","frisches Brot","kalte Milch","neue Ideen"],["Dativ ohne Artikel","gutem Wein","frischem Brot","kalter Milch","neuen Ideen"]],"headersEn":["case","masculine","neuter","feminine","plural"],"firstColumnEn":["nominative after der / die / das","accusative after der / die / das","dative after der / die / das","nominative after ein / eine","accusative after ein / eine","dative after ein / eine","nominative without article","accusative without article","dative without article"]},"traps":["Falsch: Ich habe einen neue Job. – Richtig: Ich habe einen neuen Job.","Falsch: Das ist ein interessant Buch. – Richtig: Das ist ein interessantes Buch.","Falsch: Wir wohnen in einer kleine Wohnung. – Richtig: Wir wohnen in einer kleinen Wohnung.","Falsch: Die neue Nachbarn sind freundlich. – Richtig: Die neuen Nachbarn sind freundlich."],"trapsEn":["Wrong: Ich habe einen neue Job. – Right: Ich habe einen neuen Job.","Wrong: Das ist ein interessant Buch. – Right: Das ist ein interessantes Buch.","Wrong: Wir wohnen in einer kleine Wohnung. – Right: Wir wohnen in einer kleinen Wohnung.","Wrong: Die neue Nachbarn sind freundlich. – Right: Die neuen Nachbarn sind freundlich."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.modalverben', 10, 'topic', 'Modalverben', 'Modal verbs', 'Modalverben braucht man in jeder Prüfungsaufgabe, und die Reihenfolge im Satz sowie die Vergangenheit sind typische Fehlerquellen.', 'Modal verbs are needed in every exam task, and both the word order in the sentence and the past tense are typical sources of error.', '{"rule":"Die Modalverben sind können, müssen, dürfen, sollen, wollen und möchten. Sie stehen an der zweiten Stelle im Satz, und der Infinitiv steht ganz am Ende: Ich muss morgen früh aufstehen. können heißt Fähigkeit oder Möglichkeit, müssen heißt Pflicht, dürfen heißt Erlaubnis, sollen heißt Rat oder Auftrag, wollen heißt eigener Wille und möchten ist ein höflicher Wunsch. Wichtig ist der Unterschied: nicht müssen heißt, es ist nicht nötig, aber nicht dürfen heißt, es ist verboten. Die Vergangenheit bildet man meist mit dem Präteritum: ich konnte, musste, durfte, sollte, wollte.","ruleEn":"The modal verbs are können, müssen, dürfen, sollen, wollen and möchten. They stand in second position in the sentence and the infinitive goes right at the end: Ich muss morgen früh aufstehen. können means ability or possibility, müssen means obligation, dürfen means permission, sollen means advice or an instruction, wollen means your own will, and möchten is a polite wish. The important difference is: nicht müssen means it is not necessary, but nicht dürfen means it is forbidden. The past is usually formed with the preterite: ich konnte, musste, durfte, sollte, wollte.","pattern":"Subjekt + Modalverb (Position 2) + ... + Infinitiv (am Ende)","patternEn":"subject + modal verb (position 2) + ... + infinitive (at the end)","examples":[{"de":"Ich kann am Samstag leider nicht kommen.","en":"Unfortunately I cannot come on Saturday.","note":"können: keine Möglichkeit"},{"de":"Du musst das Formular bis Freitag abgeben.","en":"You have to hand in the form by Friday.","note":"müssen: Pflicht, trennbares Verb am Ende"},{"de":"Hier darf man nicht parken, das ist verboten.","en":"You are not allowed to park here, that is forbidden.","note":"dürfen: Erlaubnis, verneint ein Verbot"},{"de":"Du solltest mehr schlafen und weniger arbeiten.","en":"You should sleep more and work less.","note":"sollen im Präteritum als Rat: solltest"},{"de":"Ich möchte mich für den Kurs anmelden.","en":"I would like to register for the course.","note":"möchten: höflicher Wunsch, Reflexivverb am Ende"},{"de":"Wir wollten dich gestern anrufen, aber wir hatten kein Netz.","en":"We wanted to call you yesterday, but we had no signal.","note":"Präteritum von wollen: wollten"}],"traps":["Falsch: Ich muss aufstehen morgen früh. – Richtig: Ich muss morgen früh aufstehen.","Falsch: Du musst hier nicht rauchen. – Richtig: Du darfst hier nicht rauchen, denn es ist verboten.","Falsch: Ich habe gestern nicht kommen gekonnt. – Richtig: Ich konnte gestern nicht kommen.","Falsch: Ich will mich anmelden für den Kurs. – Richtig: Ich will mich für den Kurs anmelden."],"trapsEn":["Wrong: Ich muss aufstehen morgen früh. – Right: Ich muss morgen früh aufstehen.","Wrong: Du musst hier nicht rauchen. – Right: Du darfst hier nicht rauchen, because it is forbidden.","Wrong: Ich habe gestern nicht kommen gekonnt. – Right: Ich konnte gestern nicht kommen.","Wrong: Ich will mich anmelden für den Kurs. – Right: Ich will mich für den Kurs anmelden."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.komparativ-superlativ', 11, 'topic', 'Komparativ und Superlativ', 'Comparative and superlative', 'Vergleiche kommen in der Prüfung oft vor, zum Beispiel beim Beschreiben von Bildern oder beim Argumentieren, und als und wie werden sehr häufig verwechselt.', 'Comparisons come up often in the exam, for example when describing pictures or arguing a point, and als and wie are very often confused.', '{"rule":"Mit dem Komparativ vergleicht man zwei Dinge: Adjektiv + -er. Mit dem Superlativ sagt man, dass etwas am größten ist: am + Adjektiv + -sten. Kurze Adjektive bekommen oft einen Umlaut: alt wird älter und am ältesten, groß wird größer und am größten. Einige Formen sind unregelmäßig: gut wird besser und am besten, viel wird mehr und am meisten, gern wird lieber und am liebsten, hoch wird höher und am höchsten. Beim Vergleich mit als steht der Komparativ (Mein Bruder ist älter als ich), und wenn beide gleich sind, steht wie: Er ist genauso groß wie ich.","ruleEn":"With the comparative you compare two things: adjective + -er. With the superlative you say that something is the most: am + adjective + -sten. Short adjectives often take an umlaut: alt becomes älter and am ältesten, groß becomes größer and am größten. Some forms are irregular: gut becomes besser and am besten, viel becomes mehr and am meisten, gern becomes lieber and am liebsten, hoch becomes höher and am höchsten. In a comparison with als you use the comparative (Mein Bruder ist älter als ich), and when both are equal you use wie: Er ist genauso groß wie ich.","pattern":"Komparativ: ...-er als | Superlativ: am ...-sten","patternEn":"comparative: ...-er als | superlative: am ...-sten","examples":[{"de":"Mein Bruder ist zwei Jahre älter als ich.","en":"My brother is two years older than me.","note":"Komparativ + als"},{"de":"Berlin ist viel größer als meine Heimatstadt.","en":"Berlin is much bigger than my home town.","note":"groß wird größer, mit Umlaut"},{"de":"Im Sommer ist es hier am wärmsten.","en":"In summer it is warmest here.","note":"Superlativ: am wärmsten"},{"de":"Ich fahre lieber mit dem Zug als mit dem Auto.","en":"I prefer travelling by train to going by car.","note":"gern wird lieber, Vergleich mit als"},{"de":"Deutsch finde ich schwieriger als Englisch, aber Mathe ist am schwierigsten.","en":"I find German more difficult than English, but maths is the most difficult.","note":"Komparativ und Superlativ zusammen"},{"de":"Meine neue Wohnung ist genauso teuer wie die alte.","en":"My new flat is just as expensive as the old one.","note":"gleicher Grad: genauso ... wie"}],"table":{"headers":["Positiv","Komparativ","Superlativ"],"rows":[["gut","besser","am besten"],["viel","mehr","am meisten"],["gern","lieber","am liebsten"],["hoch","höher","am höchsten"],["alt","älter","am ältesten"],["groß","größer","am größten"],["warm","wärmer","am wärmsten"],["nah","näher","am nächsten"]],"headersEn":["positive","comparative","superlative"]},"traps":["Falsch: Mein Bruder ist älter wie ich. – Richtig: Mein Bruder ist älter als ich.","Falsch: Er ist genauso groß als ich. – Richtig: Er ist genauso groß wie ich.","Beim Komparativ vergessen viele den Umlaut: Es heißt älter, größer, wärmer und höher.","Falsch: Ich trinke am gernsten Tee. – Richtig: Ich trinke am liebsten Tee."],"trapsEn":["Wrong: Mein Bruder ist älter wie ich. – Right: Mein Bruder ist älter als ich.","Wrong: Er ist genauso groß als ich. – Right: Er ist genauso groß wie ich.","Many people forget the umlaut in the comparative: it is älter, größer, wärmer and höher.","Wrong: Ich trinke am gernsten Tee. – Right: Ich trinke am liebsten Tee."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.trennbare-verben', 12, 'topic', 'Trennbare Verben', 'Separable verbs', 'Trennbare Verben sind im Alltag überall, und wenn die Vorsilbe an der falschen Stelle steht, klingt der ganze Satz falsch.', 'Separable verbs are everywhere in everyday language, and if the prefix is in the wrong place the whole sentence sounds wrong.', '{"rule":"Trennbare Verben haben eine Vorsilbe, die im Hauptsatz allein ans Satzende geht: anrufen wird Ich rufe dich später an. Nach einem Modalverb bleibt das Verb zusammen und steht als Infinitiv am Ende: Ich muss dich später anrufen. Auch beim Infinitiv mit zu bleibt das Verb zusammen, und zu steht in der Mitte: Ich habe vergessen, dich anzurufen. Im Nebensatz steht das ganze Verb zusammen am Ende: ..., weil ich dich anrufe. Typische trennbare Verben sind anrufen, aufstehen, einkaufen, mitkommen, anfangen, ausgehen, fernsehen, einladen, aufräumen und stattfinden.","ruleEn":"Separable verbs have a prefix that goes to the end of the sentence on its own in a main clause: anrufen becomes Ich rufe dich später an. After a modal verb the verb stays together and stands as an infinitive at the end: Ich muss dich später anrufen. With the infinitive with zu the verb also stays together, and zu goes in the middle: Ich habe vergessen, dich anzurufen. In a subordinate clause the whole verb stands together at the end: ..., weil ich dich anrufe. Typical separable verbs are anrufen, aufstehen, einkaufen, mitkommen, anfangen, ausgehen, fernsehen, einladen, aufräumen and stattfinden.","pattern":"Vorsilbe + Verb (Position 2) ... Vorsilbe am Satzende","patternEn":"prefix + verb (position 2) ... prefix at the end of the sentence","examples":[{"de":"Ich rufe dich heute Abend an.","en":"I will call you this evening.","note":"anrufen: an geht ans Satzende"},{"de":"Ich muss jeden Morgen um sechs Uhr aufstehen.","en":"I have to get up at six o’clock every morning.","note":"nach muss bleibt aufstehen zusammen"},{"de":"Wir kaufen samstags immer im Supermarkt ein.","en":"On Saturdays we always shop at the supermarket.","note":"einkaufen: ein geht ans Satzende"},{"de":"Der Kurs fängt am Montag um neun Uhr an.","en":"The course starts on Monday at nine o’clock.","note":"anfangen: an geht ans Satzende"},{"de":"Das Konzert findet am Samstag im Stadtpark statt.","en":"The concert takes place in the city park on Saturday.","note":"stattfinden: statt geht ans Satzende"},{"de":"Ich habe vergessen, meine Freunde einzuladen.","en":"I forgot to invite my friends.","note":"einladen wird einzuladen, zu steht in der Mitte"}],"traps":["Falsch: Ich rufe an dich heute Abend. – Richtig: Ich rufe dich heute Abend an.","Falsch: Ich muss um sechs Uhr auf stehen. – Richtig: Ich muss um sechs Uhr aufstehen.","Falsch: Kommst du mit uns mitkommen? – Richtig: Kommst du mit uns mit?","Falsch: Ich habe vor, meine Freunde einladen zu. – Richtig: Ich habe vor, meine Freunde einzuladen."],"trapsEn":["Wrong: Ich rufe an dich heute Abend. – Right: Ich rufe dich heute Abend an.","Wrong: Ich muss um sechs Uhr auf stehen. – Right: Ich muss um sechs Uhr aufstehen.","Wrong: Kommst du mit uns mitkommen? – Right: Kommst du mit uns mit?","Wrong: Ich habe vor, meine Freunde einladen zu. – Right: Ich habe vor, meine Freunde einzuladen."]}'::jsonb),
    ('grammar-guide', 'telc-deutsch-b1.grammar-guide.passiv', 13, 'topic', 'Passiv mit werden', 'Passive with werden', 'Das Passiv braucht man für formelle Briefe, für Anleitungen und für Beschreibungen, und in der Prüfung wirkt es sofort fortgeschritten.', 'The passive is needed for formal letters, for instructions and for descriptions, and in the exam it immediately sounds advanced.', '{"rule":"Im Passiv steht das Wichtige am Anfang, und wer etwas macht, ist oft nicht so wichtig. Man bildet es mit werden plus Partizip II: Das Formular wird ausgefüllt. Wenn man die Person nennen will, nimmt man von + Dativ: Der Brief wird von der Chefin unterschrieben. Mit einem Modalverb steht das Modalverb an der zweiten Stelle und am Ende werden + Partizip II: Das Formular muss bis Freitag ausgefüllt werden. Die Vergangenheit heißt wurde + Partizip II (Das Haus wurde 1990 gebaut), und im Passiv steht immer das Partizip II und nie der Infinitiv.","ruleEn":"In the passive the important thing comes first, and who does something is often less important. It is formed with werden plus the past participle: Das Formular wird ausgefüllt. If you want to name the person, you use von + dative: Der Brief wird von der Chefin unterschrieben. With a modal verb the modal verb stands in second position and werden + past participle at the end: Das Formular muss bis Freitag ausgefüllt werden. The past is wurde + past participle (Das Haus wurde 1990 gebaut), and the passive always uses the past participle and never the infinitive.","pattern":"werden + Partizip II (+ von + Dativ)","patternEn":"werden + past participle (+ von + dative)","examples":[{"de":"Das Formular wird im Büro ausgefüllt.","en":"The form is filled in at the office.","note":"Präsens Passiv: wird + Partizip II"},{"de":"Die Rechnung wird von der Chefin unterschrieben.","en":"The invoice is signed by the boss.","note":"von + Dativ nennt die Person"},{"de":"Das Formular muss bis Freitag ausgefüllt werden.","en":"The form must be filled in by Friday.","note":"Modalpassiv: Modalverb + Partizip II + werden"},{"de":"Das neue Krankenhaus wurde letztes Jahr gebaut.","en":"The new hospital was built last year.","note":"Vergangenheit: wurde + Partizip II"},{"de":"In unserer Schule werden viele Sprachen unterrichtet.","en":"Many languages are taught at our school.","note":"Plural: werden + Partizip II"},{"de":"Die Getränke werden von den Kollegen mitgebracht.","en":"The drinks are brought along by the colleagues.","note":"von + Dativ Plural, Partizip mitgebracht"}],"traps":["Falsch: Das Formular wird ausfüllen. – Richtig: Das Formular wird ausgefüllt.","Falsch: Das Formular muss ausgefüllt. – Richtig: Das Formular muss ausgefüllt werden, denn im Modalpassiv steht werden am Ende.","Falsch: Die Rechnung wird von die Chefin unterschrieben. – Richtig: Die Rechnung wird von der Chefin unterschrieben.","Falsch: Das Formular wird ausgefüllt werden. – Richtig: Das Formular wird ausgefüllt."],"trapsEn":["Wrong: Das Formular wird ausfüllen. – Right: Das Formular wird ausgefüllt.","Wrong: Das Formular muss ausgefüllt. – Right: Das Formular muss ausgefüllt werden, because the modal passive puts werden at the end.","Wrong: Die Rechnung wird von die Chefin unterschrieben. – Right: Die Rechnung wird von der Chefin unterschrieben.","Wrong: Das Formular wird ausgefüllt werden. – Right: Das Formular wird ausgefüllt."]}'::jsonb),
    ('core-grammar', 'telc-deutsch-b1.core-grammar.funktionswoerter', 0, 'tier', 'Konnektoren & Funktionswörter', NULL, 'In Sprachbausteine Teil 2 wird fast nur diese Wortart geprüft: Wer Konnektor und Wortstellung sicher beherrscht, holt die meisten Punkte.', NULL, '{"items":[{"id":"aber","de":"aber (Verb an Position 2, Hauptsatz)","en":"but","pos":"conj","example":"Ich möchte kommen, aber ich habe am Samstag leider keine Zeit.","exampleEn":"I would like to come, but unfortunately I have no time on Saturday.","note":"Aber ist eine nebenordnende Konjunktion: Position 0, danach folgt ganz normal Subjekt und Verb."},{"id":"denn","de":"denn (Verb an Position 2, Hauptsatz)","en":"because, for","pos":"conj","example":"Wir bleiben zu Hause, denn das Wetter ist heute sehr schlecht.","exampleEn":"We are staying home, because the weather is very bad today.","note":"Denn leitet keinen Nebensatz ein: Das Verb bleibt an Position 2 (nicht ans Satzende)."},{"id":"sondern","de":"sondern (Verb an Position 2, nach Verneinung)","en":"but rather","pos":"conj","example":"Er wohnt nicht in Berlin, sondern in Potsdam bei seiner Familie.","exampleEn":"He does not live in Berlin, but rather in Potsdam with his family.","note":"Sondern steht nur nach einer Verneinung und korrigiert sie; sonst benutzt man aber."},{"id":"deshalb","de":"deshalb (Verb an Position 2)","en":"therefore, that is why","pos":"adv","example":"Es hat stark geregnet, deshalb sind wir zu Hause geblieben.","exampleEn":"It rained heavily, therefore we stayed at home.","note":"Deshalb ist ein Adverb: Es besetzt Position 1, das Verb bleibt Position 2."},{"id":"deswegen","de":"deswegen (Verb an Position 2)","en":"that is why, because of that","pos":"adv","example":"Der Zug hatte Verspätung, deswegen kam ich zu spät.","exampleEn":"The train was delayed, that is why I arrived late.","note":"Bedeutung wie deshalb; wichtig ist nur die Wortstellung: Verb direkt nach deswegen."},{"id":"trotzdem","de":"trotzdem (Verb an Position 2)","en":"nevertheless, anyway","pos":"adv","example":"Ich war sehr müde, trotzdem habe ich noch meine Hausaufgaben gemacht.","exampleEn":"I was very tired, nevertheless I still did my homework.","note":"Trotzdem ist ein Adverb der Folge; nicht mit obwohl verwechseln (obwohl = Nebensatz)."},{"id":"obwohl","de":"obwohl (Verb am Satzende)","en":"although","pos":"conj","example":"Obwohl es geregnet hat, sind wir spazieren gegangen.","exampleEn":"Although it rained, we went for a walk.","note":"Obwohl leitet einen Nebensatz ein: Das konjugierte Verb steht am Ende."},{"id":"weil","de":"weil (Verb am Satzende)","en":"because","pos":"conj","example":"Ich komme heute nicht, weil ich länger arbeiten muss.","exampleEn":"I am not coming today because I have to work longer.","note":"Weil-Satz: Verb am Satzende. Verwechslungsgefahr mit denn (Verb Position 2)."},{"id":"da","de":"da (Verb am Satzende)","en":"since, as","pos":"conj","example":"Da ich kein Auto habe, fahre ich mit dem Bus zur Arbeit.","exampleEn":"Since I do not have a car, I take the bus to work.","note":"Da ist wie weil, steht aber oft am Satzanfang, wenn der Grund schon bekannt ist."},{"id":"damit","de":"damit (Verb am Satzende)","en":"so that","pos":"conj","example":"Ich lerne jeden Tag Vokabeln, damit ich die Prüfung bestehe.","exampleEn":"I learn vocabulary every day so that I pass the exam.","note":"Damit + Nebensatz mit Verb am Ende, wenn die Subjekte verschieden sind."},{"id":"wenn","de":"wenn (Verb am Satzende)","en":"when, if, whenever","pos":"conj","example":"Wenn ich Zeit habe, besuche ich meine Eltern am Wochenende.","exampleEn":"When I have time, I visit my parents at the weekend.","note":"Wenn steht bei Gegenwart, Zukunft und bei wiederholten Handlungen."},{"id":"als","de":"als (Verb am Satzende, einmalige Vergangenheit)","en":"when (single past event)","pos":"conj","example":"Als ich klein war, haben wir jedes Jahr in Italien Urlaub gemacht.","exampleEn":"When I was little, we went on holiday in Italy every year.","note":"Als nur für ein einmaliges Ereignis in der Vergangenheit; Wiederholung = wenn."},{"id":"falls","de":"falls (Verb am Satzende)","en":"in case, if","pos":"conj","example":"Falls Sie Fragen haben, rufen Sie mich bitte einfach an.","exampleEn":"In case you have any questions, please just call me.","note":"Falls ist wie wenn, aber nur bedingt möglich: Nebensatz mit Verb am Ende."},{"id":"bevor","de":"bevor (Verb am Satzende)","en":"before","pos":"conj","example":"Bevor ich zur Arbeit gehe, frühstücke ich immer mit meiner Familie.","exampleEn":"Before I go to work, I always have breakfast with my family.","note":"Bevor + Nebensatz; im Hauptsatz steht oft zuerst oder danach als Signalwort."},{"id":"nachdem","de":"nachdem (Verb am Satzende, Zeitenfolge)","en":"after","pos":"conj","example":"Nachdem ich gefrühstückt hatte, bin ich zur Arbeit gefahren.","exampleEn":"After I had had breakfast, I drove to work.","note":"Nachdem verlangt Zeitenfolge: Perfekt/Plusquamperfekt im Nebensatz, Präsens/Präteritum im Hauptsatz."},{"id":"waehrend","de":"während (Verb am Satzende)","en":"while, during","pos":"conj","example":"Während ich koche, hört mein Mann Musik im Wohnzimmer.","exampleEn":"While I cook, my husband listens to music in the living room.","note":"Als Konjunktion mit Nebensatz; als Präposition steht während + Genitiv."},{"id":"seit","de":"seit (Verb am Satzende, temporal)","en":"since","pos":"conj","example":"Seit er in München arbeitet, fährt er jeden Tag mit dem Rad.","exampleEn":"Since he has been working in Munich, he cycles every day.","note":"Seit + Dativ als Präposition; als Konjunktion steht das Verb am Satzende."},{"id":"bis","de":"bis (Verb am Satzende)","en":"until","pos":"conj","example":"Ich bleibe noch hier, bis der Regen endlich aufhört.","exampleEn":"I will stay here until the rain finally stops.","note":"Bis als Konjunktion ohne dass: Nebensatz mit Verb am Ende."},{"id":"ausserdem","de":"außerdem (Verb an Position 2)","en":"besides, moreover","pos":"adv","example":"Wir haben wenig Zeit, außerdem ist das Museum heute geschlossen.","exampleEn":"We have little time, besides, the museum is closed today.","note":"Außerdem fügt ein weiteres Argument hinzu und steht auf Position 1 oder 3."},{"id":"schliesslich","de":"schließlich (Verb an Position 2)","en":"finally, after all","pos":"adv","example":"Nach langem Warten kam der Bus schließlich doch noch an.","exampleEn":"After a long wait, the bus finally arrived after all.","note":"Schließlich steht für das letzte Argument oder ein Ereignis am Ende."},{"id":"zuerst","de":"zuerst (Verb an Position 2)","en":"first (of all)","pos":"adv","example":"Zuerst lesen Sie bitte den Text, dann beantworten Sie die Fragen.","exampleEn":"First please read the text, then answer the questions.","note":"Reihenfolge im Text: zuerst - dann - danach - schließlich - zuletzt."},{"id":"danach","de":"danach (Verb an Position 2)","en":"afterwards, after that","pos":"adv","example":"Zuerst machen wir die Übung, danach gehen wir noch ein Eis essen.","exampleEn":"First we do the exercise, afterwards we will get some ice cream.","note":"Danach ordnet Ereignisse zeitlich; das Verb folgt direkt auf Position 2."},{"id":"zuletzt","de":"zuletzt (Verb an Position 2)","en":"lastly, finally","pos":"adv","example":"Zuletzt möchte ich mich bei allen herzlich für die Hilfe bedanken.","exampleEn":"Lastly I would like to thank everyone warmly for the help.","note":"Zuletzt schließt eine Aufzählung ab; typisch in Briefen und Berichten."},{"id":"jedoch","de":"jedoch (Verb an Position 2)","en":"however","pos":"adv","example":"Das Hotel war ziemlich teuer, jedoch sehr sauber und ruhig.","exampleEn":"The hotel was quite expensive, however very clean and quiet.","note":"Jedoch kann auch mitten im Satz stehen, das Verb bleibt dann an Position 2."},{"id":"allerdings","de":"allerdings (Verb an Position 2)","en":"however, though","pos":"adv","example":"Ich würde gerne kommen, allerdings habe ich am Montag keine Zeit.","exampleEn":"I would like to come, however I have no time on Monday.","note":"Allerdings ist eine Einschränkung und steht meist auf Position 1 oder 3."},{"id":"also","de":"also (Verb an Position 2)","en":"so, therefore","pos":"adv","example":"Ich habe heute keine Zeit, also treffen wir uns morgen.","exampleEn":"I have no time today, so we will meet tomorrow.","note":"Also zeigt die Folge; nicht mit dem Füllwort also (= na ja) verwechseln."},{"id":"sonst","de":"sonst (Verb an Position 2)","en":"otherwise","pos":"adv","example":"Beeil dich bitte, sonst verpassen wir noch den Zug.","exampleEn":"Please hurry up, otherwise we will miss the train.","note":"Sonst nennt die negative Folge, wenn etwas nicht geschieht."},{"id":"entweder_oder","de":"entweder ... oder (Verb an Position 2)","en":"either ... or","pos":"conj","example":"Entweder fahren wir mit dem Auto oder wir nehmen den Zug.","exampleEn":"Either we go by car or we take the train.","note":"Zweiteilige Konjunktion: entweder steht auf Position 1, oder leitet den zweiten Hauptsatz ein."},{"id":"sowohl_als_auch","de":"sowohl ... als auch (Verb an Position 2)","en":"both ... and","pos":"conj","example":"Sie spricht sowohl Englisch als auch ein bisschen Französisch.","exampleEn":"She speaks both English and a little French.","note":"Sowohl ... als auch verbindet zwei gleichwertige Satzteile; das Verb steht im Plural."},{"id":"weder_noch","de":"weder ... noch (Verb an Position 2)","en":"neither ... nor","pos":"conj","example":"Er hat weder Zeit noch Lust, heute ins Kino zu gehen.","exampleEn":"He has neither time nor desire to go to the cinema today.","note":"Weder ... noch ist selbst verneinend: kein zusätzliches nicht im Satz."},{"id":"nicht_nur_sondern_auch","de":"nicht nur ... sondern auch (Verb an Position 2)","en":"not only ... but also","pos":"conj","example":"Sie ist nicht nur klug, sondern auch sehr freundlich zu allen.","exampleEn":"She is not only clever but also very friendly to everyone.","note":"Nach sondern auch wiederholt man das Subjekt nicht, das Verb bleibt Position 2."},{"id":"je_desto","de":"je ... desto (Verb direkt nach desto)","en":"the ... the (comparison)","pos":"conj","example":"Je länger ich warte, desto nervöser werde ich.","exampleEn":"The longer I wait, the more nervous I get.","note":"Je + Komparativ am Satzanfang, desto + Komparativ, dann sofort das Verb."},{"id":"besonders","de":"besonders (Adverb, betont ein Wort)","en":"especially, particularly","pos":"adv","example":"Ich mag italienisches Essen besonders gern, vor allem Pizza.","exampleEn":"I especially like Italian food, above all pizza.","note":"Besonders steht vor dem Wort, das hervorgehoben wird, oft vor gern oder gut."},{"id":"dafuer","de":"dafür (Pronominaladverb, Verb an Position 2)","en":"for that, in return","pos":"adv","example":"Der Kurs war teuer, dafür haben wir sehr viel gelernt.","exampleEn":"The course was expensive, in return we learned a lot.","note":"Dafür weist auf einen Gegensatz oder auf eine Sache zurück; Frageform: wofür?"},{"id":"damals","de":"damals (Adverb der Vergangenheit, Verb an Position 2)","en":"back then, at that time","pos":"adv","example":"Damals habe ich in einer kleinen Stadt bei Köln gewohnt.","exampleEn":"Back then I lived in a small town near Cologne.","note":"Damals bezieht sich auf eine frühere Zeit; Zeiten: Präteritum oder Perfekt."},{"id":"gerne","de":"gerne (Adverb, steht nach dem Verb)","en":"gladly, with pleasure","pos":"adv","example":"Ich helfe Ihnen gerne, wenn Sie noch Fragen haben.","exampleEn":"I will gladly help you if you still have questions.","note":"Gerne steht direkt nach dem konjugierten Verb; Komparativ: lieber, Superlativ: am liebsten."},{"id":"wann","de":"wann (Fragewort, indirekte Frage: Verb am Satzende)","en":"when (question word)","pos":"adv","example":"Wissen Sie, wann der nächste Zug nach Berlin fährt?","exampleEn":"Do you know when the next train to Berlin leaves?","note":"Wann fragt nach einem Zeitpunkt; wenn ist eine Konjunktion, wann ein Fragewort."},{"id":"dass","de":"dass (Verb am Satzende)","en":"that","pos":"conj","example":"Ich hoffe, dass du bald wieder ganz gesund wirst.","exampleEn":"I hope that you get completely well again soon.","note":"Dass-Satz: Verb am Ende; im Hauptsatz steht oft hoffen, glauben, sagen oder finden."},{"id":"ob","de":"ob (Verb am Satzende, indirekte Ja/Nein-Frage)","en":"whether, if","pos":"conj","example":"Ich weiß nicht, ob er heute Abend zu Hause ist.","exampleEn":"I do not know whether he is at home this evening.","note":"Ob steht bei indirekten Ja/Nein-Fragen; bei Ergänzungsfragen nimmt man das Fragewort."},{"id":"um_zu","de":"um ... zu (Infinitiv am Satzende)","en":"in order to","pos":"phrase","example":"Ich lerne jeden Tag Deutsch, um in Deutschland studieren zu können.","exampleEn":"I learn German every day in order to be able to study in Germany.","note":"Um ... zu + Infinitiv nur bei gleichem Subjekt; sonst damit + Nebensatz."},{"id":"statt_zu","de":"statt ... zu (Infinitiv am Satzende)","en":"instead of","pos":"phrase","example":"Statt zu Hause zu bleiben, gehen wir heute zusammen schwimmen.","exampleEn":"Instead of staying at home, we are going swimming together today.","note":"Statt ... zu + Infinitiv bei gleichem Subjekt; sonst statt dass + Nebensatz."},{"id":"ohne_zu","de":"ohne ... zu (Infinitiv am Satzende)","en":"without","pos":"phrase","example":"Sie ging aus dem Haus, ohne sich von uns zu verabschieden.","exampleEn":"She left the house without saying goodbye to us.","note":"Ohne ... zu + Infinitiv bei gleichem Subjekt; sonst ohne dass + Nebensatz."},{"id":"so_dass","de":"so dass (Verb am Satzende, Folge)","en":"so that (as a result)","pos":"conj","example":"Es hat sehr stark geregnet, so dass die Straße überschwemmt war.","exampleEn":"It rained very heavily, so that the street was flooded.","note":"So dass nennt die Folge: Nebensatz mit Verb am Satzende, oft nach einem Komma."},{"id":"indem","de":"indem (Verb am Satzende, Mittel)","en":"by (doing something)","pos":"conj","example":"Man lernt eine Sprache am besten, indem man täglich spricht.","exampleEn":"You learn a language best by speaking every day.","note":"Indem gibt das Mittel an, wie man etwas erreicht: Verb am Satzende."},{"id":"anstatt_dass","de":"anstatt dass (Verb am Satzende)","en":"instead of (with different subjects)","pos":"conj","example":"Anstatt dass er mir hilft, sitzt er nur vor dem Fernseher.","exampleEn":"Instead of helping me, he just sits in front of the television.","note":"Anstatt dass benutzt man, wenn die Subjekte in beiden Sätzen verschieden sind."}]}'::jsonb),
    ('core-grammar', 'telc-deutsch-b1.core-grammar.konjunktiv2', 1, 'tier', 'Konjunktiv II & Höflichkeit', NULL, 'Höfliche Bitten und Wünsche im Brief oder in der E-Mail sind ein Standardteil der Prüfung und bringen sichere Punkte.', NULL, '{"items":[{"id":"haette_gern","de":"Ich hätte gern ...","en":"I would like ...","pos":"phrase","example":"Ich hätte gern einen Termin beim Arzt am nächsten Montag.","exampleEn":"I would like an appointment with the doctor next Monday.","note":"Höflicher Wunsch: hätte gern + Akkusativ; im Restaurant und am Telefon sehr häufig."},{"id":"waere","de":"Es wäre ... / Das wäre ...","en":"It would be ...","pos":"verb","example":"Es wäre sehr nett, wenn Sie mir kurz antworten könnten.","exampleEn":"It would be very nice if you could answer me briefly.","note":"Konjunktiv II von sein: wäre; typisch für höfliche Wünsche und irreale Bedingungen."},{"id":"wuerde","de":"Ich würde ... + Infinitiv","en":"I would ...","pos":"verb","example":"Ich würde mich sehr über eine schnelle Antwort freuen.","exampleEn":"I would be very happy about a quick answer.","note":"Würde + Infinitiv ersetzt die meisten Konjunktiv-II-Formen, z. B. ich würde kommen."},{"id":"koennte","de":"Könnte ich bitte ... ?","en":"Could I please ...?","pos":"verb","example":"Könnte ich bitte noch eine Frage zum Kurs stellen?","exampleEn":"Could I please ask one more question about the course?","note":"Könnte ist die höfliche Form von können und steht oft am Satzanfang."},{"id":"muesste","de":"Ich müsste ... (höflich, indirekt)","en":"I would have to ...","pos":"verb","example":"Ich müsste den Termin leider auf nächste Woche verschieben.","exampleEn":"Unfortunately I would have to postpone the appointment to next week.","note":"Müsste klingt viel höflicher als muss; gut für Absagen und Bitten."},{"id":"duerfte","de":"Dürfte ich ... ?","en":"May I ...?","pos":"verb","example":"Dürfte ich Sie um eine kurze Auskunft bitten?","exampleEn":"May I ask you for some brief information?","note":"Dürfte ich ... ? ist die höflichste Form, um um Erlaubnis zu bitten."},{"id":"sollte","de":"Sie sollten ... (Ratschlag)","en":"You should ...","pos":"verb","example":"Sie sollten sich für den Kurs früh genug anmelden.","exampleEn":"You should register for the course early enough.","note":"Sollte ist die höfliche Empfehlung: Sie sollten + Infinitiv."},{"id":"wuerden_sie","de":"Würden Sie ... ? (höfliche Bitte)","en":"Would you ...?","pos":"phrase","example":"Würden Sie mir bitte die genaue Adresse schicken?","exampleEn":"Would you please send me the exact address?","note":"Würden Sie + Infinitiv ist eine sehr höfliche Bitte an eine fremde Person."},{"id":"waeren_sie_so_nett","de":"Wären Sie so nett und ... / Wären Sie so nett, mir zu ...","en":"Would you be so kind as to ...","pos":"phrase","example":"Wären Sie so nett und schicken mir die Unterlagen per E-Mail?","exampleEn":"Would you be so kind as to send me the documents by email?","note":"Sehr höfliche Bitte: Wären Sie so nett und + Verb, oder Wären Sie so nett, ... zu + Infinitiv."},{"id":"koennten_sie_mir_sagen","de":"Könnten Sie mir bitte sagen, ... ?","en":"Could you please tell me ...?","pos":"phrase","example":"Könnten Sie mir bitte sagen, wann der Kurs beginnt?","exampleEn":"Could you please tell me when the course begins?","note":"Nach dieser Einleitung folgt eine indirekte Frage mit Verb am Satzende."},{"id":"ich_wuerde_gern_wissen_ob","de":"Ich würde gern wissen, ob ...","en":"I would like to know whether ...","pos":"phrase","example":"Ich würde gern wissen, ob noch Plätze im Kurs frei sind.","exampleEn":"I would like to know whether there are still places free in the course.","note":"Höfliche indirekte Frage mit ob; das Verb steht am Ende des Nebensatzes."},{"id":"ich_haette_eine_frage","de":"Ich hätte eine Frage zu ...","en":"I would have a question about ...","pos":"phrase","example":"Ich hätte eine Frage zu den Kurszeiten am Freitag.","exampleEn":"I would have a question about the course times on Friday.","note":"Höflicher Gesprächsbeginn am Telefon oder in der E-Mail: Ich hätte eine Frage zu + Dativ."},{"id":"es_waere_schoen_wenn","de":"Es wäre schön, wenn ...","en":"It would be nice if ...","pos":"conj","example":"Es wäre schön, wenn wir uns nächste Woche treffen könnten.","exampleEn":"It would be nice if we could meet next week.","note":"Höflicher Wunsch: Hauptsatz mit wäre, wenn-Satz mit Verb am Ende."},{"id":"an_ihrer_stelle_wuerde_ich","de":"An Ihrer Stelle würde ich ...","en":"If I were you, I would ...","pos":"phrase","example":"An Ihrer Stelle würde ich den Termin lieber verschieben.","exampleEn":"If I were you, I would rather postpone the appointment.","note":"Höflicher Ratschlag: An Ihrer Stelle (formell) / An deiner Stelle (informell) + würde ich."},{"id":"koennten_sie_mir_bitte_helfen","de":"Könnten Sie mir bitte helfen?","en":"Could you please help me?","pos":"phrase","example":"Könnten Sie mir bitte bei der Anmeldung helfen?","exampleEn":"Could you please help me with the registration?","note":"Höfliche Bitte mit Dativobjekt: jemandem helfen + Dativ."},{"id":"ich_braeuchte","de":"Ich bräuchte ...","en":"I would need ...","pos":"verb","example":"Ich bräuchte noch ein paar Informationen zu Ihrem Angebot.","exampleEn":"I would need a few more pieces of information about your offer.","note":"Bräuchte ist der höfliche Konjunktiv II von brauchen; perfekt für Anfragen."},{"id":"konj_muessten","de":"müssten (Konjunktiv II von müssen)","en":"would have to","pos":"verb","example":"Wir müssten uns beeilen, sonst verpassen wir den Zug.","exampleEn":"We would have to hurry, otherwise we will miss the train.","note":"Konjunktiv II von müssen: drückt eine vorsichtige Notwendigkeit aus, keinen Befehl."}]}'::jsonb),
    ('core-grammar', 'telc-deutsch-b1.core-grammar.verbpraeposition', 2, 'tier', 'Verben mit Präposition', NULL, 'Verb und Präposition mit dem richtigen Fall sind ein Kernthema in Sprachbausteine Teil 1 und kosten sonst schnell Punkte im Brief.', NULL, '{"items":[{"id":"sich_interessieren_fuer","de":"sich interessieren für + Akkusativ","en":"to be interested in","pos":"verb","example":"Ich interessiere mich sehr für Musik und fremde Sprachen.","exampleEn":"I am very interested in music and foreign languages.","note":"Feste Verbindung mit Akkusativ: sich interessieren für + Akkusativ."},{"id":"warten_auf","de":"warten auf + Akkusativ","en":"to wait for","pos":"verb","example":"Wir warten schon seit einer Stunde auf den Bus.","exampleEn":"We have been waiting for the bus for an hour already.","note":"Feste Verbindung mit Akkusativ: warten auf + Akkusativ."},{"id":"sich_freuen_ueber","de":"sich freuen über + Akkusativ","en":"to be glad about (something already received)","pos":"verb","example":"Ich freue mich sehr über das Geschenk von meinen Eltern.","exampleEn":"I am very happy about the present from my parents.","note":"Feste Verbindung mit Akkusativ; über = etwas ist schon da."},{"id":"sich_freuen_auf","de":"sich freuen auf + Akkusativ","en":"to look forward to","pos":"verb","example":"Wir freuen uns schon sehr auf unseren Urlaub in Spanien.","exampleEn":"We are already very much looking forward to our holiday in Spain.","note":"Feste Verbindung mit Akkusativ; auf = etwas kommt erst noch."},{"id":"denken_an","de":"denken an + Akkusativ","en":"to think of, to think about","pos":"verb","example":"Ich denke oft an meine Familie und meine alten Freunde.","exampleEn":"I often think of my family and my old friends.","note":"Feste Verbindung mit Akkusativ: denken an + Akkusativ."},{"id":"sich_kuemmern_um","de":"sich kümmern um + Akkusativ","en":"to take care of","pos":"verb","example":"Sie kümmert sich jeden Tag um ihre kranke Großmutter.","exampleEn":"She takes care of her sick grandmother every day.","note":"Feste Verbindung mit Akkusativ: sich kümmern um + Akkusativ."},{"id":"teilnehmen_an","de":"teilnehmen an + Dativ","en":"to take part in","pos":"verb","example":"Ich möchte gern an einem Deutschkurs am Abend teilnehmen.","exampleEn":"I would like to take part in an evening German course.","note":"Feste Verbindung mit Dativ: teilnehmen an + Dativ; trennbar: ich nehme teil."},{"id":"sich_bewerben_um","de":"sich bewerben um + Akkusativ","en":"to apply for","pos":"verb","example":"Ich bewerbe mich um einen Praktikumsplatz in einer großen Firma.","exampleEn":"I am applying for an internship place in a large company.","note":"Feste Verbindung mit Akkusativ: sich bewerben um + Akkusativ."},{"id":"sich_erinnern_an","de":"sich erinnern an + Akkusativ","en":"to remember","pos":"verb","example":"Ich erinnere mich noch gut an meinen ersten Schultag.","exampleEn":"I still remember my first school day well.","note":"Feste Verbindung mit Akkusativ: sich erinnern an + Akkusativ."},{"id":"bitten_um","de":"bitten um + Akkusativ","en":"to ask for, to request","pos":"verb","example":"Ich bitte Sie um eine kurze Antwort bis Freitag.","exampleEn":"I ask you for a short answer by Friday.","note":"Feste Verbindung mit Akkusativ: jemanden um etwas bitten."},{"id":"sich_aergern_ueber","de":"sich ärgern über + Akkusativ","en":"to be annoyed about","pos":"verb","example":"Ich ärgere mich sehr über die laute Musik im Nachbarhaus.","exampleEn":"I am very annoyed about the loud music in the neighbouring house.","note":"Feste Verbindung mit Akkusativ: sich ärgern über + Akkusativ."},{"id":"sich_entscheiden_fuer","de":"sich entscheiden für + Akkusativ","en":"to decide on, to choose","pos":"verb","example":"Wir haben uns für das kleinere Hotel am Meer entschieden.","exampleEn":"We decided on the smaller hotel by the sea.","note":"Feste Verbindung mit Akkusativ: sich entscheiden für + Akkusativ."},{"id":"gehoeren_zu","de":"gehören zu + Dativ","en":"to belong to","pos":"verb","example":"Diese alten Fotos gehören zu meiner Kindheit in Polen.","exampleEn":"These old photos belong to my childhood in Poland.","note":"Feste Verbindung mit Dativ: gehören zu + Dativ."},{"id":"bestehen_aus","de":"bestehen aus + Dativ","en":"to consist of","pos":"verb","example":"Die Prüfung besteht aus einem schriftlichen und einem mündlichen Teil.","exampleEn":"The exam consists of a written and an oral part.","note":"Feste Verbindung mit Dativ: bestehen aus + Dativ."},{"id":"sich_beschaeftigen_mit","de":"sich beschäftigen mit + Dativ","en":"to occupy oneself with, to deal with","pos":"verb","example":"In meiner Freizeit beschäftige ich mich gern mit Fotografie.","exampleEn":"In my free time I like to occupy myself with photography.","note":"Feste Verbindung mit Dativ: sich beschäftigen mit + Dativ."},{"id":"abhaengen_von","de":"abhängen von + Dativ","en":"to depend on","pos":"verb","example":"Unser Urlaub hängt leider vom Wetter und vom Geld ab.","exampleEn":"Unfortunately our holiday depends on the weather and on money.","note":"Feste Verbindung mit Dativ: abhängen von + Dativ; trennbar: es hängt ab."},{"id":"achten_auf","de":"achten auf + Akkusativ","en":"to pay attention to","pos":"verb","example":"Bitte achten Sie auf die genaue Schreibweise der Wörter.","exampleEn":"Please pay attention to the exact spelling of the words.","note":"Feste Verbindung mit Akkusativ: achten auf + Akkusativ."},{"id":"sich_vorbereiten_auf","de":"sich vorbereiten auf + Akkusativ","en":"to prepare for","pos":"verb","example":"Ich bereite mich seit drei Monaten auf die Prüfung vor.","exampleEn":"I have been preparing for the exam for three months.","note":"Feste Verbindung mit Akkusativ: sich vorbereiten auf + Akkusativ."},{"id":"traeumen_von","de":"träumen von + Dativ","en":"to dream of","pos":"verb","example":"Sie träumt von einem eigenen kleinen Haus am See.","exampleEn":"She dreams of her own little house by the lake.","note":"Feste Verbindung mit Dativ: träumen von + Dativ."},{"id":"sprechen_ueber","de":"sprechen über + Akkusativ","en":"to talk about","pos":"verb","example":"Wir haben lange über unsere Pläne für den Sommer gesprochen.","exampleEn":"We talked for a long time about our plans for the summer.","note":"Feste Verbindung mit Akkusativ: sprechen über + Akkusativ."},{"id":"sich_unterhalten_ueber","de":"sich unterhalten über + Akkusativ","en":"to converse about, to chat about","pos":"verb","example":"Die Kollegen unterhalten sich in der Pause über die neue Chefin.","exampleEn":"The colleagues chat about the new boss during the break.","note":"Feste Verbindung mit Akkusativ: sich unterhalten über + Akkusativ."},{"id":"sich_bedanken_fuer","de":"sich bedanken für + Akkusativ","en":"to thank for","pos":"verb","example":"Ich bedanke mich herzlich für Ihre schnelle Hilfe.","exampleEn":"I thank you warmly for your quick help.","note":"Feste Verbindung mit Akkusativ: sich bedanken für + Akkusativ."},{"id":"sich_entschuldigen_bei","de":"sich entschuldigen bei + Dativ","en":"to apologise to","pos":"verb","example":"Ich entschuldige mich bei Ihnen für die späte Antwort.","exampleEn":"I apologise to you for the late answer.","note":"Person mit Dativ: sich bei jemandem entschuldigen; der Grund steht mit für + Akkusativ."},{"id":"fragen_nach","de":"fragen nach + Dativ","en":"to ask about, to ask for","pos":"verb","example":"Der Gast fragt nach dem Weg zum Hauptbahnhof.","exampleEn":"The guest asks for the way to the main station.","note":"Feste Verbindung mit Dativ: fragen nach + Dativ."},{"id":"suchen_nach","de":"suchen nach + Dativ","en":"to search for","pos":"verb","example":"Wir suchen noch nach einer günstigen Wohnung in der Nähe.","exampleEn":"We are still searching for an affordable flat nearby.","note":"Suchen + Akkusativ ist auch möglich; mit nach steht immer der Dativ."},{"id":"sich_treffen_mit","de":"sich treffen mit + Dativ","en":"to meet (with)","pos":"verb","example":"Ich treffe mich am Freitag mit meiner besten Freundin.","exampleEn":"I am meeting my best friend on Friday.","note":"Feste Verbindung mit Dativ: sich treffen mit + Dativ."},{"id":"zufrieden_sein_mit","de":"zufrieden sein mit + Dativ","en":"to be satisfied with","pos":"phrase","example":"Meine Chefin ist mit meiner Arbeit sehr zufrieden.","exampleEn":"My boss is very satisfied with my work.","note":"Feste Verbindung mit Dativ: zufrieden sein mit + Dativ."},{"id":"angst_haben_vor","de":"Angst haben vor + Dativ","en":"to be afraid of","pos":"phrase","example":"Viele Kinder haben Angst vor großen Hunden im Park.","exampleEn":"Many children are afraid of big dogs in the park.","note":"Feste Verbindung mit Dativ: Angst haben vor + Dativ."},{"id":"lust_haben_auf","de":"Lust haben auf + Akkusativ","en":"to feel like (doing something)","pos":"phrase","example":"Hast du heute Abend Lust auf einen Film im Kino?","exampleEn":"Do you feel like a film at the cinema tonight?","note":"Feste Verbindung mit Akkusativ: Lust haben auf + Akkusativ."},{"id":"zeit_haben_fuer","de":"Zeit haben für + Akkusativ","en":"to have time for","pos":"phrase","example":"Am Wochenende habe ich endlich Zeit für meine Familie.","exampleEn":"At the weekend I finally have time for my family.","note":"Feste Verbindung mit Akkusativ: Zeit haben für + Akkusativ."},{"id":"sich_verabreden_mit","de":"sich verabreden mit + Dativ","en":"to arrange to meet with","pos":"verb","example":"Ich habe mich für Samstag mit zwei Kollegen verabredet.","exampleEn":"I have arranged to meet two colleagues for Saturday.","note":"Feste Verbindung mit Dativ: sich verabreden mit + Dativ."},{"id":"sich_informieren_ueber","de":"sich informieren über + Akkusativ","en":"to inform oneself about","pos":"verb","example":"Ich möchte mich über die Preise der Kurse informieren.","exampleEn":"I would like to inform myself about the prices of the courses.","note":"Feste Verbindung mit Akkusativ: sich informieren über + Akkusativ."},{"id":"sich_anmelden_fuer","de":"sich anmelden für + Akkusativ","en":"to register for","pos":"verb","example":"Sie müssen sich bis Freitag für den Kurs anmelden.","exampleEn":"You have to register for the course by Friday.","note":"Feste Verbindung mit Akkusativ: sich anmelden für + Akkusativ."},{"id":"sich_beschweren_ueber","de":"sich beschweren über + Akkusativ","en":"to complain about","pos":"verb","example":"Die Nachbarn beschweren sich über den Lärm im Treppenhaus.","exampleEn":"The neighbours complain about the noise in the stairwell.","note":"Feste Verbindung mit Akkusativ: sich beschweren über + Akkusativ."},{"id":"rechnen_mit","de":"rechnen mit + Dativ","en":"to reckon with, to expect","pos":"verb","example":"Für morgen müssen wir mit starkem Regen rechnen.","exampleEn":"For tomorrow we have to expect heavy rain.","note":"Feste Verbindung mit Dativ: rechnen mit + Dativ."},{"id":"sich_verstehen_mit","de":"sich verstehen mit + Dativ","en":"to get along with","pos":"verb","example":"Ich verstehe mich sehr gut mit meinen neuen Kollegen.","exampleEn":"I get along very well with my new colleagues.","note":"Feste Verbindung mit Dativ: sich verstehen mit + Dativ."},{"id":"verbprep_dankbar","de":"dankbar sein für + Akkusativ","en":"to be grateful for","pos":"phrase","example":"Ich bin Ihnen sehr dankbar für Ihre schnelle Hilfe.","exampleEn":"I am very grateful to you for your quick help.","note":"dankbar für + Akkusativ; die Person steht im Dativ: Ich bin dir / Ihnen dankbar."}]}'::jsonb),
    ('core-grammar', 'telc-deutsch-b1.core-grammar.nomenverb', 3, 'tier', 'Nomen-Verb-Verbindungen', NULL, 'Diese festen Wendungen wirken im Brief und im mündlichen Ausdruck sofort sicher und werden in telc B1 gern erwartet.', NULL, '{"items":[{"id":"eine_entscheidung_treffen","de":"eine Entscheidung treffen","en":"to make a decision","pos":"phrase","example":"Wir müssen bald eine Entscheidung über unseren Urlaub treffen.","exampleEn":"We soon have to make a decision about our holiday.","note":"Nicht machen, sondern treffen: eine Entscheidung treffen."},{"id":"einen_termin_vereinbaren","de":"einen Termin vereinbaren","en":"to arrange an appointment","pos":"phrase","example":"Ich möchte mit dem Arzt einen neuen Termin vereinbaren.","exampleEn":"I would like to arrange a new appointment with the doctor.","note":"Formell für Termine: einen Termin vereinbaren (auch: einen Termin machen)."},{"id":"einen_termin_absagen","de":"einen Termin absagen","en":"to cancel an appointment","pos":"phrase","example":"Leider muss ich meinen Termin am Montag absagen.","exampleEn":"Unfortunately I have to cancel my appointment on Monday.","note":"Gegenteil von vereinbaren: einen Termin absagen."},{"id":"bescheid_geben","de":"Bescheid geben","en":"to let someone know","pos":"phrase","example":"Bitte geben Sie mir bis Freitag über das Projekt Bescheid.","exampleEn":"Please let me know by Friday.","note":"Jemandem Bescheid geben: die Person steht im Dativ."},{"id":"bescheid_sagen","de":"Bescheid sagen","en":"to tell someone, to inform someone","pos":"phrase","example":"Ich sage dir morgen Bescheid, ob ich mitkomme.","exampleEn":"I will tell you tomorrow whether I am coming along.","note":"Umgangssprachlich für kurze Information: jemandem Bescheid sagen."},{"id":"eine_rolle_spielen","de":"eine Rolle spielen","en":"to play a role","pos":"phrase","example":"Das Wetter spielt bei unserer Planung eine große Rolle.","exampleEn":"The weather plays a big role in our planning.","note":"Oft mit Adjektiv: eine wichtige, große oder kleine Rolle spielen."},{"id":"kritik_ueben","de":"Kritik üben","en":"to criticise","pos":"phrase","example":"In der Sitzung hat der Chef deutliche Kritik geübt.","exampleEn":"In the meeting the boss criticised clearly.","note":"Formell: Kritik üben an + Dativ; umgangssprachlich: kritisieren."},{"id":"ruecksicht_nehmen_auf","de":"Rücksicht nehmen auf + Akkusativ","en":"to show consideration for","pos":"phrase","example":"Bitte nehmen Sie Rücksicht auf die älteren Teilnehmer.","exampleEn":"Please show consideration for the older participants.","note":"Feste Wendung mit Akkusativ: Rücksicht nehmen auf + Akkusativ."},{"id":"in_frage_kommen","de":"in Frage kommen","en":"to be an option, to be considered","pos":"phrase","example":"Für den Job kommen nur Bewerber mit Erfahrung in Frage.","exampleEn":"Only applicants with experience are an option for the job.","note":"Meist verneint oder einschränkend: für etwas in Frage kommen."},{"id":"zur_verfuegung_stehen","de":"zur Verfügung stehen","en":"to be available","pos":"phrase","example":"Für Fragen stehe ich Ihnen gerne jederzeit zur Verfügung.","exampleEn":"I am gladly available to you at any time for questions.","note":"Jemandem zur Verfügung stehen; typische Höflichkeitsformel im Brief."},{"id":"abschied_nehmen","de":"Abschied nehmen","en":"to say goodbye","pos":"phrase","example":"Am letzten Tag haben wir traurig Abschied genommen.","exampleEn":"On the last day we sadly said goodbye.","note":"Von jemandem Abschied nehmen: die Person steht mit von + Dativ."},{"id":"einen_antrag_stellen","de":"einen Antrag stellen","en":"to submit an application","pos":"phrase","example":"Ich habe beim Amt einen Antrag auf Urlaub gestellt.","exampleEn":"I submitted an application for leave at the office.","note":"Formell für Behörden: einen Antrag stellen; Zweck mit auf + Akkusativ."},{"id":"eine_frage_stellen","de":"eine Frage stellen","en":"to ask a question","pos":"phrase","example":"Darf ich Ihnen noch eine kurze Frage stellen?","exampleEn":"May I ask you one more short question?","note":"Eine Frage stellen, nicht machen; die Person steht im Dativ."},{"id":"sport_treiben","de":"Sport treiben","en":"to do sport","pos":"phrase","example":"Ich treibe dreimal pro Woche Sport im Fitnessstudio.","exampleEn":"I do sport three times a week at the gym.","note":"Feste Wendung: Sport treiben (auch: Sport machen)."},{"id":"den_haushalt_machen","de":"den Haushalt machen","en":"to do the housework","pos":"phrase","example":"Am Samstag machen wir zusammen den ganzen Haushalt.","exampleEn":"On Saturday we do the whole housework together.","note":"Feste Wendung: den Haushalt machen; auch: im Haushalt helfen."},{"id":"verantwortung_uebernehmen","de":"Verantwortung übernehmen","en":"to take on responsibility","pos":"phrase","example":"In diesem Projekt übernehme ich die Verantwortung für das Team.","exampleEn":"In this project I take on responsibility for the team.","note":"Untrennbar: Verantwortung übernehmen; für etwas/jemanden + Akkusativ."},{"id":"einen_vortrag_halten","de":"einen Vortrag halten","en":"to give a talk","pos":"phrase","example":"Am Donnerstag hält unsere Lehrerin einen Vortrag über Umwelt.","exampleEn":"On Thursday our teacher gives a talk about the environment.","note":"Nicht machen, sondern halten: einen Vortrag halten."},{"id":"platz_nehmen","de":"Platz nehmen","en":"to take a seat","pos":"phrase","example":"Bitte nehmen Sie doch Platz, der Arzt kommt gleich.","exampleEn":"Please do take a seat, the doctor will come soon.","note":"Formelle Aufforderung: Nehmen Sie Platz! / Bitte Platz nehmen."},{"id":"in_kontakt_bleiben","de":"in Kontakt bleiben","en":"to stay in contact","pos":"phrase","example":"Nach dem Kurs möchten wir gern in Kontakt bleiben.","exampleEn":"After the course we would like to stay in contact.","note":"Mit jemandem in Kontakt bleiben; auch: in Kontakt sein."},{"id":"unter_druck_stehen","de":"unter Druck stehen","en":"to be under pressure","pos":"phrase","example":"Vor der Prüfung stehen viele Kursteilnehmer unter Druck.","exampleEn":"Before the exam many course participants are under pressure.","note":"Feste Wendung mit Dativ: unter Druck stehen."},{"id":"rad_fahren","de":"Rad fahren","en":"to cycle, to ride a bike","pos":"phrase","example":"Im Sommer fahre ich jeden Morgen mit dem Rad zur Arbeit.","exampleEn":"In summer I cycle to work every morning.","note":"Rad fahren ist trennbar: ich fahre Rad; auch: mit dem Rad fahren."},{"id":"zu_fuss_gehen","de":"zu Fuß gehen","en":"to walk, to go on foot","pos":"phrase","example":"Zum Bahnhof gehe ich lieber zu Fuß, das dauert zehn Minuten.","exampleEn":"I prefer to walk to the station, that takes ten minutes.","note":"Feste Wendung: zu Fuß gehen; nicht mit dem Fuß gehen."},{"id":"einen_eindruck_machen","de":"einen Eindruck machen","en":"to make an impression","pos":"phrase","example":"Das neue Café macht auf mich einen sehr guten Eindruck.","exampleEn":"The new café makes a very good impression on me.","note":"Auf jemanden einen guten oder schlechten Eindruck machen."},{"id":"hilfe_leisten","de":"Hilfe leisten","en":"to provide help","pos":"phrase","example":"Die Freiwilligen leisten den Familien im Dorf große Hilfe.","exampleEn":"The volunteers provide great help to the families in the village.","note":"Formell: jemandem Hilfe leisten; umgangssprachlich: helfen."},{"id":"einen_vorschlag_machen","de":"einen Vorschlag machen","en":"to make a suggestion","pos":"phrase","example":"Ich möchte Ihnen einen Vorschlag für unser Treffen machen.","exampleEn":"I would like to make you a suggestion for our meeting.","note":"Jemandem einen Vorschlag machen; auch: einen Vorschlag bringen."},{"id":"geld_verdienen","de":"Geld verdienen","en":"to earn money","pos":"phrase","example":"Mit diesem Nebenjob kann ich gut Geld verdienen.","exampleEn":"With this side job I can earn good money.","note":"Feste Wendung: Geld verdienen; nicht Geld machen."}]}'::jsonb),
    ('core-phrases', 'telc-deutsch-b1.core-phrases.redemittel-schreiben', 0, 'tier', 'Redemittel: Schreiben', NULL, 'Diese formelhaften Wendungen bringen im schriftlichen Teil sofort Punkte, weil sie den formellen Briefaufbau und die Höflichkeit sichern.', NULL, '{"items":[{"id":"rede_schreiben_anrede_1","de":"Sehr geehrte Damen und Herren,","en":"Dear Sir or Madam,","pos":"phrase","example":"Sehr geehrte Damen und Herren, ich schreibe Ihnen wegen Ihrer Anzeige.","exampleEn":"Dear Sir or Madam, I am writing to you regarding your advertisement.","note":"Formelle Anrede, wenn der Name unbekannt ist. Danach klein weiterschreiben."},{"id":"rede_schreiben_anrede_2","de":"Sehr geehrte Frau Weber,","en":"Dear Ms Weber,","pos":"phrase","example":"Sehr geehrte Frau Weber, vielen Dank für Ihre freundliche Einladung.","exampleEn":"Dear Ms Weber, thank you very much for your kind invitation.","note":"Formelle Anrede mit Namen. Nach der Anrede geht es klein weiter."},{"id":"rede_schreiben_anrede_3","de":"Sehr geehrter Herr Bauer,","en":"Dear Mr Bauer,","pos":"phrase","example":"Sehr geehrter Herr Bauer, ich habe eine Frage zu Ihrem Kurs.","exampleEn":"Dear Mr Bauer, I have a question about your course.","note":"Formell bei Männern: ''Sehr geehrter Herr'' plus Nachname."},{"id":"rede_schreiben_anrede_4","de":"Liebe Frau Klein,","en":"Dear Ms Klein,","pos":"phrase","example":"Liebe Frau Klein, ich hoffe, es geht Ihnen gut.","exampleEn":"Dear Ms Klein, I hope you are well.","note":"Informelle, aber höfliche Anrede. Bei Männern: ''Lieber Herr ...''."},{"id":"rede_schreiben_anrede_5","de":"Hallo Thomas,","en":"Hello Thomas,","pos":"phrase","example":"Hallo Thomas, hast du am Wochenende Zeit für ein Treffen?","exampleEn":"Hello Thomas, do you have time for a meeting at the weekend?","note":"Sehr informelle Anrede für Freunde; im Examen nur bei privaten Texten."},{"id":"rede_schreiben_einstieg_1","de":"Ich schreibe Ihnen, weil ...","en":"I am writing to you because ...","pos":"phrase","example":"Ich schreibe Ihnen, weil ich mich für den Deutschkurs anmelden möchte.","exampleEn":"I am writing to you because I would like to register for the German course.","note":"Formeller Einstieg in Brief oder E-Mail. Das Verb steht am Ende des Nebensatzes."},{"id":"rede_schreiben_einstieg_2","de":"Ich schreibe dir, weil ...","en":"I am writing to you because ...","pos":"phrase","example":"Ich schreibe dir, weil ich am Samstag leider nicht kommen kann.","exampleEn":"I am writing to you because unfortunately I cannot come on Saturday.","note":"Informelle Variante mit ''dir''. Gut für E-Mails an Freunde."},{"id":"rede_schreiben_grund_1","de":"Ich melde mich, weil ...","en":"I am getting in touch because ...","pos":"phrase","example":"Ich melde mich, weil ich eine Frage zu Ihrer Wohnung habe.","exampleEn":"I am getting in touch because I have a question about your flat.","note":"Alternative zum Einstieg; klingt freundlich und unkompliziert."},{"id":"rede_schreiben_grund_2","de":"Der Grund für meine E-Mail ist, dass ...","en":"The reason for my email is that ...","pos":"phrase","example":"Der Grund für meine E-Mail ist, dass ich den Termin verschieben muss.","exampleEn":"The reason for my email is that I have to postpone the appointment.","note":"Sehr klarer, formeller Grund. ''dass'' schickt das Verb ans Satzende."},{"id":"rede_schreiben_bitte_1","de":"Könnten Sie mir bitte ... ?","en":"Could you please ... ?","pos":"phrase","example":"Könnten Sie mir bitte die genaue Adresse des Kurses schicken?","exampleEn":"Could you please send me the exact address of the course?","note":"Höfliche Bitte im Konjunktiv II. Danach steht der Infinitiv am Satzende."},{"id":"rede_schreiben_bitte_2","de":"Ich würde Sie bitten, ...","en":"I would ask you to ...","pos":"phrase","example":"Ich würde Sie bitten, mir bis Freitag zu antworten.","exampleEn":"I would ask you to reply to me by Friday.","note":"Sehr höfliche Bitte im formellen Register; danach Infinitiv mit ''zu''."},{"id":"rede_schreiben_bitte_3","de":"Könntest du mir bitte ... ?","en":"Could you please ... ?","pos":"phrase","example":"Könntest du mir bitte deinen Fahrradschlüssel bis morgen leihen?","exampleEn":"Could you please lend me your bicycle key until tomorrow?","note":"Informelle Bitte mit ''du''. Gut für Nachrichten an Freunde."},{"id":"rede_schreiben_frage_1","de":"Könnten Sie mir sagen, ob ... ?","en":"Could you tell me whether ... ?","pos":"phrase","example":"Könnten Sie mir sagen, ob der Kurs am Montag beginnt?","exampleEn":"Could you tell me whether the course starts on Monday?","note":"Höfliche indirekte Frage; ''ob'' leitet den Nebensatz ein."},{"id":"rede_schreiben_frage_2","de":"Ich würde gern wissen, wann ...","en":"I would like to know when ...","pos":"phrase","example":"Ich würde gern wissen, wann die Prüfung genau stattfindet.","exampleEn":"I would like to know when the exam takes place exactly.","note":"Höfliche Frage, auch ohne Fragezeichen möglich; Verb am Ende."},{"id":"rede_schreiben_entschuldigung_1","de":"Entschuldigen Sie bitte, dass ...","en":"Please excuse the fact that ...","pos":"phrase","example":"Entschuldigen Sie bitte, dass ich mich erst heute melde.","exampleEn":"Please excuse the fact that I am only getting in touch today.","note":"Formelle Entschuldigung; sehr typisch für Absagen im Examen."},{"id":"rede_schreiben_entschuldigung_2","de":"Leider muss ich Ihnen mitteilen, dass ...","en":"Unfortunately I have to inform you that ...","pos":"phrase","example":"Leider muss ich Ihnen mitteilen, dass ich nicht kommen kann.","exampleEn":"Unfortunately I have to inform you that I cannot come.","note":"Höfliche Form für schlechte Nachrichten, zum Beispiel für eine Absage."},{"id":"rede_schreiben_entschuldigung_3","de":"Entschuldige bitte, dass ...","en":"Sorry that ...","pos":"phrase","example":"Entschuldige bitte, dass ich gestern nicht angerufen habe.","exampleEn":"Sorry that I did not call yesterday.","note":"Informelle Entschuldigung mit ''du''."},{"id":"rede_schreiben_dank_1","de":"Vielen Dank im Voraus.","en":"Many thanks in advance.","pos":"phrase","example":"Vielen Dank im Voraus für Ihre schnelle und freundliche Antwort.","exampleEn":"Many thanks in advance for your quick and friendly reply.","note":"Standardformel am Ende einer Bitte um Information."},{"id":"rede_schreiben_dank_2","de":"Ich möchte mich herzlich bedanken für ...","en":"I would like to sincerely thank you for ...","pos":"phrase","example":"Ich möchte mich herzlich bedanken für Ihre Hilfe beim Umzug.","exampleEn":"I would like to sincerely thank you for your help with the move.","note":"Sehr herzlicher, aber noch formeller Dank; danach folgt der Akkusativ."},{"id":"rede_schreiben_freude_1","de":"Ich würde mich sehr freuen, wenn ...","en":"I would be very pleased if ...","pos":"phrase","example":"Ich würde mich sehr freuen, wenn Sie mir bald antworten.","exampleEn":"I would be very pleased if you replied to me soon.","note":"Höflicher Wunsch; ''wenn'' schickt das Verb ans Satzende."},{"id":"rede_schreiben_freude_2","de":"Ich freue mich auf deine Antwort.","en":"I look forward to your reply.","pos":"phrase","example":"Ich freue mich auf deine Antwort und grüße dich herzlich.","exampleEn":"I look forward to your reply and send you warm regards.","note":"Informeller Schlusssatz; formell: ''Ich freue mich auf Ihre Antwort.''"},{"id":"rede_schreiben_meinung_1","de":"Aus meiner Sicht ist es wichtig, dass ...","en":"From my point of view it is important that ...","pos":"phrase","example":"Aus meiner Sicht ist es wichtig, dass Kinder regelmäßig Sport machen.","exampleEn":"From my point of view it is important that children do sport regularly.","note":"Meinung formell ausdrücken; Alternative: ''Meiner Meinung nach ...''."},{"id":"rede_schreiben_meinung_2","de":"Ich bin davon überzeugt, dass ...","en":"I am convinced that ...","pos":"phrase","example":"Ich bin davon überzeugt, dass ein Verein viele Vorteile hat.","exampleEn":"I am convinced that a club has many advantages.","note":"Starke Meinung; gut für den Schluss eines Arguments."},{"id":"rede_schreiben_vorschlag_1","de":"Ich möchte Ihnen folgenden Vorschlag machen: ...","en":"I would like to make you the following suggestion: ...","pos":"phrase","example":"Ich möchte Ihnen folgenden Vorschlag machen: Wir treffen uns am Freitag.","exampleEn":"I would like to make you the following suggestion: let us meet on Friday.","note":"Formeller Vorschlag im Brief; danach folgt ein Hauptsatz."},{"id":"rede_schreiben_schluss_1","de":"Mit freundlichen Grüßen","en":"Yours sincerely","pos":"phrase","example":"Am Ende des Briefes schreibe ich ''Mit freundlichen Grüßen'' und meinen Namen.","exampleEn":"At the end of the letter I write ''Yours sincerely'' and my name.","note":"Standardgruß im formellen Brief; danach folgt die Unterschrift."},{"id":"rede_schreiben_schluss_2","de":"Mit besten Grüßen","en":"Best regards","pos":"phrase","example":"Nach dem Termin beende ich die E-Mail mit ''Mit besten Grüßen''.","exampleEn":"After the appointment I end the email with ''Best regards''.","note":"Etwas persönlicher als ''Mit freundlichen Grüßen'', aber noch formell."},{"id":"rede_schreiben_schluss_3","de":"Viele Grüße","en":"Many greetings","pos":"phrase","example":"In der E-Mail an meinen Kollegen stehen am Ende ''Viele Grüße''.","exampleEn":"In the email to my colleague, ''Many greetings'' appears at the end.","note":"Neutral-freundlicher Gruß; passt für Bekannte und Kollegen."},{"id":"rede_schreiben_schluss_4","de":"Bis bald","en":"See you soon","pos":"phrase","example":"Bis bald, ich freue mich schon auf unser Treffen am Montag.","exampleEn":"See you soon, I am already looking forward to our meeting on Monday.","note":"Informeller Schluss für Freunde; oft mit einem Komma weitergeführt."}]}'::jsonb),
    ('core-phrases', 'telc-deutsch-b1.core-phrases.redemittel-sprechen', 1, 'tier', 'Redemittel: Sprechen', NULL, 'Mit diesen Redemitteln kann man alle drei Teile der mündlichen Prüfung flüssig und strukturiert bewältigen.', NULL, '{"items":[{"id":"rede_sprechen_praesentation_1","de":"Ich möchte Ihnen ... vorstellen.","en":"I would like to present ... to you.","pos":"phrase","example":"Ich möchte Ihnen heute meine Heimatstadt Hamburg kurz vorstellen.","exampleEn":"Today I would like to briefly present my home town of Hamburg to you.","note":"Teil 1: typischer Einstieg in die Präsentation. ''Ihnen'' ist Dativ."},{"id":"rede_sprechen_praesentation_2","de":"Ich habe ... gewählt, weil ...","en":"I chose ... because ...","pos":"phrase","example":"Ich habe das Thema Reisen gewählt, weil ich gern reise.","exampleEn":"I chose the topic of travel because I like travelling.","note":"Begründet die Themenwahl; ''weil'' schickt das Verb ans Ende."},{"id":"rede_sprechen_praesentation_3","de":"Besonders wichtig ist, dass ...","en":"It is particularly important that ...","pos":"phrase","example":"Besonders wichtig ist, dass man im Verein schnell Freunde findet.","exampleEn":"It is particularly important that you quickly find friends in a club.","note":"Hebt einen Kernpunkt hervor. Sehr gut für die Folie geeignet."},{"id":"rede_sprechen_praesentation_4","de":"Ein Vorteil ist, dass ...","en":"One advantage is that ...","pos":"phrase","example":"Ein Vorteil ist, dass ich mit dem Fahrrad schneller bin.","exampleEn":"One advantage is that I am faster with the bicycle.","note":"Nennt ein Pro-Argument in der Präsentation."},{"id":"rede_sprechen_praesentation_5","de":"Ein Nachteil ist, dass ...","en":"One disadvantage is that ...","pos":"phrase","example":"Ein Nachteil ist, dass die Fahrkarten sehr teuer geworden sind.","exampleEn":"One disadvantage is that the tickets have become very expensive.","note":"Nennt ein Contra-Argument; in Teil 1 immer beide Seiten zeigen."},{"id":"rede_sprechen_praesentation_6","de":"Aus eigener Erfahrung kann ich sagen, dass ...","en":"From my own experience I can say that ...","pos":"phrase","example":"Aus eigener Erfahrung kann ich sagen, dass Nachhilfe wirklich hilft.","exampleEn":"From my own experience I can say that tutoring really helps.","note":"Persönlicher Beleg; macht die Präsentation lebendig."},{"id":"rede_sprechen_praesentation_7","de":"Zum Schluss möchte ich noch erwähnen, ...","en":"Finally I would like to mention ...","pos":"phrase","example":"Zum Schluss möchte ich noch erwähnen, dass Sport gesund ist.","exampleEn":"Finally I would like to mention that sport is healthy.","note":"Leitet den letzten Punkt der Präsentation ein."},{"id":"rede_sprechen_praesentation_8","de":"Vielen Dank für Ihre Aufmerksamkeit.","en":"Thank you very much for your attention.","pos":"phrase","example":"Vielen Dank für Ihre Aufmerksamkeit, jetzt beantworte ich gern Fragen.","exampleEn":"Thank you very much for your attention, now I will gladly answer questions.","note":"Fester Schlusssatz der Präsentation in Teil 1."},{"id":"rede_sprechen_praesentation_9","de":"Haben Sie noch Fragen?","en":"Do you have any questions?","pos":"phrase","example":"Haben Sie noch Fragen zu meinem Thema oder zum Verein?","exampleEn":"Do you have any questions about my topic or about the club?","note":"Höfliche Einladung zur Fragerunde nach der Präsentation."},{"id":"rede_sprechen_diskussion_1","de":"Meiner Meinung nach ...","en":"In my opinion ...","pos":"phrase","example":"Meiner Meinung nach sollten Kinder mehr draußen spielen.","exampleEn":"In my opinion children should play outside more.","note":"Teil 2: kurze Meinungsformel; danach folgt ein Hauptsatz."},{"id":"rede_sprechen_diskussion_2","de":"Ich bin der Meinung, dass ...","en":"I am of the opinion that ...","pos":"phrase","example":"Ich bin der Meinung, dass Hausarbeit gerecht aufgeteilt werden muss.","exampleEn":"I am of the opinion that housework must be shared fairly.","note":"Etwas formeller als ''Ich finde''; gut für die Diskussion."},{"id":"rede_sprechen_diskussion_3","de":"Ich finde es wichtig, dass ...","en":"I find it important that ...","pos":"phrase","example":"Ich finde es wichtig, dass Jugendliche einen Jugendclub haben.","exampleEn":"I find it important that young people have a youth club.","note":"Bewertung mit ''es wichtig''; das Verb steht am Ende des dass-Satzes."},{"id":"rede_sprechen_diskussion_4","de":"Da stimme ich dir zu, aber ...","en":"I agree with you there, but ...","pos":"phrase","example":"Da stimme ich dir zu, aber die Kosten sind wirklich sehr hoch.","exampleEn":"I agree with you there, but the costs really are very high.","note":"Zustimmen und dann widersprechen: ideal für Teil 2."},{"id":"rede_sprechen_diskussion_5","de":"Ich sehe das anders, weil ...","en":"I see it differently because ...","pos":"phrase","example":"Ich sehe das anders, weil meine Familie andere Erfahrungen gemacht hat.","exampleEn":"I see it differently because my family has had different experiences.","note":"Höflicher Widerspruch; danach immer eine Begründung geben."},{"id":"rede_sprechen_diskussion_6","de":"Auf der einen Seite ..., auf der anderen Seite ...","en":"On the one hand ..., on the other hand ...","pos":"phrase","example":"Auf der einen Seite spart man Zeit, auf der anderen Seite kostet es Geld.","exampleEn":"On the one hand you save time, on the other hand it costs money.","note":"Klassische Abwägung; zeigt dem Prüfer eine klare Struktur."},{"id":"rede_sprechen_diskussion_7","de":"Ein Argument dafür ist, dass ...","en":"One argument in favour is that ...","pos":"phrase","example":"Ein Argument dafür ist, dass man im Verein neue Leute kennenlernt.","exampleEn":"One argument in favour is that you get to know new people in a club.","note":"Pro-Argument in der Diskussion; Gegenteil: ''Ein Argument dagegen ...''."},{"id":"rede_sprechen_diskussion_8","de":"Ein Argument dagegen ist, dass ...","en":"One argument against it is that ...","pos":"phrase","example":"Ein Argument dagegen ist, dass der Beitrag jedes Jahr steigt.","exampleEn":"One argument against it is that the fee rises every year.","note":"Contra-Argument; danach passt gut ein Beispiel."},{"id":"rede_sprechen_diskussion_9","de":"Zum Beispiel ...","en":"For example ...","pos":"phrase","example":"Zum Beispiel fahre ich jeden Morgen mit der Straßenbahn.","exampleEn":"For example, I take the tram every morning.","note":"Beispiel anfügen; alternativ ''Ein Beispiel dafür ist ...''."},{"id":"rede_sprechen_diskussion_10","de":"Für mich überwiegt am Ende ...","en":"For me, in the end ... outweighs ...","pos":"phrase","example":"Für mich überwiegt am Ende der Vorteil, dass ich Zeit spare.","exampleEn":"For me, in the end the advantage that I save time outweighs everything.","note":"Fazit nach der Abwägung; sehr guter Schlusssatz in Teil 2."},{"id":"rede_sprechen_diskussion_11","de":"Das ist ein interessanter Punkt, aber ...","en":"That is an interesting point, but ...","pos":"phrase","example":"Das ist ein interessanter Punkt, aber ich sehe auch Nachteile.","exampleEn":"That is an interesting point, but I also see disadvantages.","note":"Reagiert höflich auf das Argument des Partners."},{"id":"rede_sprechen_diskussion_12","de":"Ich stimme dir voll und ganz zu.","en":"I completely agree with you.","pos":"phrase","example":"Ich stimme dir voll und ganz zu, das ist wirklich ein Problem.","exampleEn":"I completely agree with you, that really is a problem.","note":"Starke Zustimmung; gut, um Gemeinsamkeiten zu zeigen."},{"id":"rede_sprechen_planung_1","de":"Ich hätte einen Vorschlag.","en":"I would have a suggestion.","pos":"phrase","example":"Ich hätte einen Vorschlag: Wir treffen uns am Samstag im Café.","exampleEn":"I would have a suggestion: let us meet on Saturday in the café.","note":"Teil 3: höflicher Einstieg in die gemeinsame Planung."},{"id":"rede_sprechen_planung_2","de":"Wie wäre es, wenn wir ... ?","en":"How would it be if we ... ?","pos":"phrase","example":"Wie wäre es, wenn wir das Geschenk zusammen kaufen?","exampleEn":"How would it be if we bought the present together?","note":"Höflicher Vorschlag im Konjunktiv II; das Verb steht am Satzende."},{"id":"rede_sprechen_planung_3","de":"Sollen wir ... ?","en":"Shall we ... ?","pos":"phrase","example":"Sollen wir die Getränke schon am Freitag einkaufen?","exampleEn":"Shall we buy the drinks already on Friday?","note":"Einfache Frage nach der Meinung des Partners."},{"id":"rede_sprechen_planung_4","de":"Das finde ich gut, aber ...","en":"I think that is good, but ...","pos":"phrase","example":"Das finde ich gut, aber der Termin passt mir leider nicht.","exampleEn":"I think that is good, but unfortunately the date does not suit me.","note":"Zustimmung mit Einschränkung; typisch für die Planung."},{"id":"rede_sprechen_planung_5","de":"Ich könnte mich um ... kümmern.","en":"I could take care of ...","pos":"phrase","example":"Ich könnte mich um die Musik und die Getränke kümmern.","exampleEn":"I could take care of the music and the drinks.","note":"Aufgabe übernehmen; ''sich kümmern um'' steht mit Akkusativ."},{"id":"rede_sprechen_planung_6","de":"Wer übernimmt ... ?","en":"Who will take on ... ?","pos":"phrase","example":"Wer übernimmt die Aufgabe, den Saal zu reservieren?","exampleEn":"Who will take on the task of reserving the hall?","note":"Frage nach der Aufgabenverteilung in der Gruppe."},{"id":"rede_sprechen_planung_7","de":"Wann passt es dir am besten?","en":"When does it suit you best?","pos":"phrase","example":"Wann passt es dir am besten, am Freitag oder am Samstag?","exampleEn":"When does it suit you best, on Friday or on Saturday?","note":"Terminfrage an den Partner; informell mit ''dir''."},{"id":"rede_sprechen_planung_8","de":"Dann machen wir es so.","en":"Then we will do it that way.","pos":"phrase","example":"Dann machen wir es so und treffen uns um sechs Uhr.","exampleEn":"Then we will do it that way and meet at six o''clock.","note":"Fester Abschluss einer Absprache in Teil 3."},{"id":"rede_sprechen_planung_9","de":"Sind wir uns einig?","en":"Are we agreed?","pos":"phrase","example":"Sind wir uns einig oder möchtest du noch etwas ändern?","exampleEn":"Are we agreed or would you like to change something?","note":"Abschlussformel, wenn die Planung fertig ist."}]}'::jsonb),
    ('core-phrases', 'telc-deutsch-b1.core-phrases.themenwortschatz', 2, 'tier', 'Themenwortschatz', NULL, 'Zwölf Schlüsselwörter pro Prüfungsthema decken den Wortschatz ab, der in telc B1 Übungstest 1 wirklich vorkommt.', NULL, '{"items":[{"id":"thema_haus_haushalt","de":"der Haushalt","en":"the household","pos":"noun","example":"In unserem Haushalt teilen wir die Hausarbeit gerecht auf.","exampleEn":"In our household we share the housework fairly.","note":"Plural: die Haushalte."},{"id":"thema_haus_hausarbeit","de":"die Hausarbeit","en":"the housework","pos":"noun","example":"Die Hausarbeit nimmt jeden Tag fast zwei Stunden in Anspruch.","exampleEn":"The housework takes almost two hours every day.","note":"Plural: die Hausarbeiten."},{"id":"thema_haus_aufteilen","de":"aufteilen","en":"to share out, to divide up","pos":"verb","example":"Wir wollen die Hausarbeit in der Familie gerecht aufteilen.","exampleEn":"We want to share the housework in the family fairly.","note":"Perfekt: hat aufgeteilt. Trennbares Verb: ich teile auf."},{"id":"thema_haus_hausmann","de":"der Hausmann","en":"the househusband","pos":"noun","example":"Mein Bruder ist Hausmann und betreut die zwei Kinder.","exampleEn":"My brother is a househusband and looks after the two children.","note":"Plural: die Hausmänner. Weibliche Form: die Hausfrau."},{"id":"thema_haus_kinderbetreuung","de":"die Kinderbetreuung","en":"the childcare","pos":"noun","example":"Gute Kinderbetreuung ist für berufstätige Eltern besonders wichtig.","exampleEn":"Good childcare is particularly important for working parents.","note":"Plural: die Kinderbetreuungen (selten). Meist ohne Plural."},{"id":"thema_haus_erziehen","de":"erziehen","en":"to raise, to bring up","pos":"verb","example":"Eltern sollen ihre Kinder mit Geduld und Liebe erziehen.","exampleEn":"Parents should raise their children with patience and love.","note":"Perfekt: hat erzogen. Dritte Person Singular: er erzieht."},{"id":"thema_haus_familienmitglied","de":"das Familienmitglied","en":"the family member","pos":"noun","example":"Jedes Familienmitglied hilft am Wochenende im Haushalt mit.","exampleEn":"Every family member helps with the housework at the weekend.","note":"Plural: die Familienmitglieder."},{"id":"thema_haus_ehefrau","de":"die Ehefrau","en":"the wife","pos":"noun","example":"Seine Ehefrau arbeitet Teilzeit und studiert am Abend.","exampleEn":"His wife works part-time and studies in the evening.","note":"Plural: die Ehefrauen. Männliche Form: der Ehemann."},{"id":"thema_haus_versorgen","de":"versorgen","en":"to look after, to provide for","pos":"verb","example":"Sie versorgt ihre kranke Mutter jeden Tag nach der Arbeit.","exampleEn":"She looks after her sick mother every day after work.","note":"Perfekt: hat versorgt. Mit Akkusativ: jemanden versorgen."},{"id":"thema_haus_streit","de":"der Streit","en":"the argument, the quarrel","pos":"noun","example":"Wegen der Hausarbeit gibt es bei uns oft Streit.","exampleEn":"Because of the housework there are often arguments at our place.","note":"Plural: die Streite. Häufig: Streit haben, sich streiten."},{"id":"thema_haus_gleichberechtigung","de":"die Gleichberechtigung","en":"the equal rights, equality","pos":"noun","example":"Gleichberechtigung beginnt für mich schon im eigenen Haushalt.","exampleEn":"For me, equal rights begin in one''s own household.","note":"Plural: meist ohne Plural. Adjektiv: gleichberechtigt."},{"id":"thema_haus_kuemmern","de":"sich kümmern","en":"to take care of, to look after","pos":"verb","example":"Am Nachmittag kümmere ich mich um meine kleine Schwester.","exampleEn":"In the afternoon I look after my little sister.","note":"Perfekt: hat sich gekümmert. Reflexiv: ich kümmere mich um ..."},{"id":"thema_freizeit_verein","de":"der Verein","en":"the club, the association","pos":"noun","example":"Mein Verein organisiert jedes Jahr ein großes Sommerfest.","exampleEn":"My club organises a big summer festival every year.","note":"Plural: die Vereine."},{"id":"thema_freizeit_mitglied","de":"das Mitglied","en":"the member","pos":"noun","example":"Als Mitglied muss man einen kleinen Beitrag pro Jahr zahlen.","exampleEn":"As a member you have to pay a small fee per year.","note":"Plural: die Mitglieder."},{"id":"thema_freizeit_beitrag","de":"der Beitrag","en":"the fee, the contribution","pos":"noun","example":"Der Beitrag für den Verein kostet zwölf Euro im Monat.","exampleEn":"The fee for the club costs twelve euros a month.","note":"Plural: die Beiträge."},{"id":"thema_freizeit_anmelden","de":"sich anmelden","en":"to register, to sign up","pos":"verb","example":"Ich möchte mich für den Yoga-Kurs am Dienstag anmelden.","exampleEn":"I would like to register for the yoga course on Tuesday.","note":"Perfekt: hat sich angemeldet. Nomen: die Anmeldung."},{"id":"thema_freizeit_hobby","de":"das Hobby","en":"the hobby","pos":"noun","example":"Mein größtes Hobby ist Fotografieren in der freien Natur.","exampleEn":"My biggest hobby is photography in nature.","note":"Plural: die Hobbys."},{"id":"thema_freizeit_freizeitgestaltung","de":"die Freizeitgestaltung","en":"the leisure activities, the organisation of free time","pos":"noun","example":"Die Freizeitgestaltung der Jugendlichen findet heute oft online statt.","exampleEn":"Young people''s leisure activities often take place online today.","note":"Plural: meist ohne Plural."},{"id":"thema_freizeit_mannschaft","de":"die Mannschaft","en":"the team","pos":"noun","example":"Unsere Mannschaft hat am Sonntag das wichtige Spiel gewonnen.","exampleEn":"Our team won the important match on Sunday.","note":"Plural: die Mannschaften."},{"id":"thema_freizeit_training","de":"das Training","en":"the training","pos":"noun","example":"Das Training im Verein dauert immer eineinhalb Stunden.","exampleEn":"The training at the club always lasts one and a half hours.","note":"Plural: die Trainings."},{"id":"thema_freizeit_teilnehmen","de":"teilnehmen","en":"to take part, to participate","pos":"verb","example":"Ich möchte an dem Kurs am Wochenende gern teilnehmen.","exampleEn":"I would like to take part in the course at the weekend.","note":"Perfekt: hat teilgenommen. Mit Dativ: an etwas teilnehmen."},{"id":"thema_freizeit_mitgliedschaft","de":"die Mitgliedschaft","en":"the membership","pos":"noun","example":"Die Mitgliedschaft im Schwimmverein kostet leider ziemlich viel.","exampleEn":"Membership in the swimming club unfortunately costs quite a lot.","note":"Plural: die Mitgliedschaften."},{"id":"thema_freizeit_ausflug","de":"der Ausflug","en":"the trip, the excursion","pos":"noun","example":"Am Samstag machen wir einen Ausflug in die Berge.","exampleEn":"On Saturday we are going on a trip to the mountains.","note":"Plural: die Ausflüge."},{"id":"thema_freizeit_treffen","de":"sich treffen","en":"to meet","pos":"verb","example":"Wir treffen uns jeden Donnerstag im Jugendzentrum zum Spielen.","exampleEn":"We meet every Thursday at the youth centre to play.","note":"Perfekt: hat sich getroffen. Reflexiv: wir treffen uns."},{"id":"thema_reise_unterkunft","de":"die Unterkunft","en":"the accommodation","pos":"noun","example":"Die Unterkunft am See war billig, aber sehr sauber.","exampleEn":"The accommodation by the lake was cheap but very clean.","note":"Plural: die Unterkünfte."},{"id":"thema_reise_buchung","de":"die Buchung","en":"the booking","pos":"noun","example":"Nach der Buchung habe ich sofort eine Bestätigung per E-Mail bekommen.","exampleEn":"After the booking I immediately received a confirmation by email.","note":"Plural: die Buchungen."},{"id":"thema_reise_fahrkarte","de":"die Fahrkarte","en":"the ticket","pos":"noun","example":"Am Automaten kaufe ich eine Fahrkarte für die Straßenbahn.","exampleEn":"At the machine I buy a ticket for the tram.","note":"Plural: die Fahrkarten."},{"id":"thema_reise_umsteigen","de":"umsteigen","en":"to change trains, to transfer","pos":"verb","example":"In Köln muss ich in den Schnellzug nach Hamburg umsteigen.","exampleEn":"In Cologne I have to change to the express train to Hamburg.","note":"Perfekt: ist umgestiegen. Trennbares Verb, Perfekt mit ''sein''."},{"id":"thema_reise_verspaetung","de":"die Verspätung","en":"the delay","pos":"noun","example":"Der Zug nach Berlin hat heute wieder zwanzig Minuten Verspätung.","exampleEn":"The train to Berlin is twenty minutes late again today.","note":"Plural: die Verspätungen."},{"id":"thema_reise_aufenthalt","de":"der Aufenthalt","en":"the stay","pos":"noun","example":"Unser Aufenthalt in Wien dauerte leider nur drei Tage.","exampleEn":"Our stay in Vienna unfortunately lasted only three days.","note":"Plural: die Aufenthalte."},{"id":"thema_reise_gleis","de":"das Gleis","en":"the platform, the track","pos":"noun","example":"Der Zug nach München fährt heute von Gleis sieben ab.","exampleEn":"The train to Munich departs from platform seven today.","note":"Plural: die Gleise."},{"id":"thema_reise_reservierung","de":"die Reservierung","en":"the reservation","pos":"noun","example":"Ohne Reservierung bekommt man im Sommer schwer einen Platz.","exampleEn":"Without a reservation it is hard to get a seat in summer.","note":"Plural: die Reservierungen."},{"id":"thema_reise_buchen","de":"buchen","en":"to book","pos":"verb","example":"Wir buchen die Reise nach Italien schon im Januar.","exampleEn":"We book the trip to Italy already in January.","note":"Perfekt: hat gebucht. Nomen: die Buchung."},{"id":"thema_reise_koffer","de":"der Koffer","en":"the suitcase","pos":"noun","example":"Mein Koffer war zu schwer und ich musste extra zahlen.","exampleEn":"My suitcase was too heavy and I had to pay extra.","note":"Plural: die Koffer."},{"id":"thema_reise_grenze","de":"die Grenze","en":"the border","pos":"noun","example":"An der Grenze mussten wir unsere Pässe zeigen.","exampleEn":"At the border we had to show our passports.","note":"Plural: die Grenzen."},{"id":"thema_reise_verpassen","de":"verpassen","en":"to miss (a train, a bus)","pos":"verb","example":"Ich darf den letzten Bus auf keinen Fall verpassen.","exampleEn":"I must not miss the last bus under any circumstances.","note":"Perfekt: hat verpasst."},{"id":"thema_gesundheit_schlafstoerung","de":"die Schlafstörung","en":"the sleep disorder, insomnia","pos":"noun","example":"Wegen der Schlafstörung bin ich morgens immer sehr müde.","exampleEn":"Because of the sleep disorder I am always very tired in the morning.","note":"Plural: die Schlafstörungen."},{"id":"thema_gesundheit_beschwerden","de":"die Beschwerden","en":"the complaints, the symptoms","pos":"noun","example":"Der Arzt fragt zuerst nach meinen Beschwerden und meiner Vorgeschichte.","exampleEn":"The doctor first asks about my complaints and my medical history.","note":"Plural: die Beschwerden. Singular selten: die Beschwerde."},{"id":"thema_gesundheit_termin","de":"der Termin","en":"the appointment","pos":"noun","example":"Beim Arzt bekommt man oft erst in zwei Wochen einen Termin.","exampleEn":"At the doctor''s you often only get an appointment in two weeks.","note":"Plural: die Termine."},{"id":"thema_gesundheit_verschreiben","de":"verschreiben","en":"to prescribe","pos":"verb","example":"Der Arzt hat mir ein starkes Medikament verschrieben.","exampleEn":"The doctor prescribed me a strong medication.","note":"Perfekt: hat verschrieben."},{"id":"thema_gesundheit_krankenkasse","de":"die Krankenkasse","en":"the health insurance fund","pos":"noun","example":"Die Krankenkasse bezahlt in diesem Fall die ganze Behandlung.","exampleEn":"The health insurance pays for the whole treatment in this case.","note":"Plural: die Krankenkassen."},{"id":"thema_gesundheit_erholen","de":"sich erholen","en":"to recover, to rest","pos":"verb","example":"Im Urlaub am Meer kann ich mich richtig gut erholen.","exampleEn":"On holiday by the sea I can really recover well.","note":"Perfekt: hat sich erholt. Reflexiv: ich erhole mich."},{"id":"thema_gesundheit_rezept","de":"das Rezept","en":"the prescription","pos":"noun","example":"Das Rezept für die Tabletten muss ich in der Apotheke abholen.","exampleEn":"I have to pick up the prescription for the tablets at the pharmacy.","note":"Plural: die Rezepte. Achtung: ''das Rezept'' ist auch ein Kochrezept."},{"id":"thema_gesundheit_untersuchung","de":"die Untersuchung","en":"the examination, the check-up","pos":"noun","example":"Die Untersuchung beim Arzt hat zum Glück nichts Schlimmes gezeigt.","exampleEn":"Fortunately the examination at the doctor''s showed nothing serious.","note":"Plural: die Untersuchungen."},{"id":"thema_gesundheit_krankenhaus","de":"das Krankenhaus","en":"the hospital","pos":"noun","example":"Nach dem Unfall musste er zwei Wochen im Krankenhaus bleiben.","exampleEn":"After the accident he had to stay in hospital for two weeks.","note":"Plural: die Krankenhäuser."},{"id":"thema_gesundheit_tablette","de":"die Tablette","en":"the tablet, the pill","pos":"noun","example":"Nimm die Tablette bitte immer nach dem Frühstück.","exampleEn":"Please always take the tablet after breakfast.","note":"Plural: die Tabletten."},{"id":"thema_gesundheit_erkaelten","de":"sich erkälten","en":"to catch a cold","pos":"verb","example":"Im Winter erkälte ich mich leider fast jedes Jahr.","exampleEn":"In winter I unfortunately catch a cold almost every year.","note":"Perfekt: hat sich erkältet. Nomen: die Erkältung."},{"id":"thema_gesundheit_behandlung","de":"die Behandlung","en":"the treatment","pos":"noun","example":"Die Behandlung beim Zahnarzt war teuer, aber nicht schmerzhaft.","exampleEn":"The treatment at the dentist was expensive but not painful.","note":"Plural: die Behandlungen."},{"id":"thema_bildung_kurs","de":"der Kurs","en":"the course","pos":"noun","example":"Der Kurs für Computer und Internet beginnt nächsten Montag.","exampleEn":"The course for computers and internet starts next Monday.","note":"Plural: die Kurse."},{"id":"thema_bildung_nachhilfe","de":"die Nachhilfe","en":"the tutoring, the private lessons","pos":"noun","example":"In Mathematik braucht mein Sohn dringend zweimal pro Woche Nachhilfe.","exampleEn":"In maths my son urgently needs tutoring twice a week.","note":"Plural: meist ohne Plural."},{"id":"thema_bildung_zeugnis","de":"das Zeugnis","en":"the report, the certificate","pos":"noun","example":"Im Zeugnis hatte sie in allen Fächern gute Noten.","exampleEn":"In her report she had good grades in all subjects.","note":"Plural: die Zeugnisse."},{"id":"thema_bildung_anmeldung","de":"die Anmeldung","en":"the registration","pos":"noun","example":"Die Anmeldung für den Sprachkurs ist nur online möglich.","exampleEn":"Registration for the language course is only possible online.","note":"Plural: die Anmeldungen."},{"id":"thema_bildung_jugendclub","de":"der Jugendclub","en":"the youth club","pos":"noun","example":"Im Jugendclub können die Kinder nach der Schule spielen.","exampleEn":"At the youth club the children can play after school.","note":"Plural: die Jugendclubs. Auch möglich: das Jugendzentrum."},{"id":"thema_bildung_ausbildung","de":"die Ausbildung","en":"the training, the vocational training","pos":"noun","example":"Nach der Schule beginnt sie eine Ausbildung als Krankenschwester.","exampleEn":"After school she begins training as a nurse.","note":"Plural: die Ausbildungen."},{"id":"thema_bildung_pruefung","de":"die Prüfung","en":"the exam","pos":"noun","example":"Vor der Prüfung lerne ich jeden Abend zwei Stunden Vokabeln.","exampleEn":"Before the exam I study vocabulary for two hours every evening.","note":"Plural: die Prüfungen."},{"id":"thema_bildung_abschluss","de":"der Abschluss","en":"the qualification, the degree","pos":"noun","example":"Mit einem guten Abschluss findet man leichter eine Stelle.","exampleEn":"With a good qualification it is easier to find a position.","note":"Plural: die Abschlüsse."},{"id":"thema_bildung_bewerben","de":"sich bewerben","en":"to apply","pos":"verb","example":"Ich möchte mich für einen Studienplatz in Berlin bewerben.","exampleEn":"I would like to apply for a place at university in Berlin.","note":"Perfekt: hat sich beworben. Nomen: die Bewerbung."},{"id":"thema_bildung_wiederholen","de":"wiederholen","en":"to repeat, to revise","pos":"verb","example":"Vor der Prüfung wiederhole ich die wichtigsten Grammatikregeln.","exampleEn":"Before the exam I revise the most important grammar rules.","note":"Perfekt: hat wiederholt."},{"id":"thema_bildung_hausaufgabe","de":"die Hausaufgabe","en":"the homework","pos":"noun","example":"Die Hausaufgabe in Deutsch war heute besonders schwierig.","exampleEn":"The German homework was particularly difficult today.","note":"Plural: die Hausaufgaben."},{"id":"thema_bildung_besuchen","de":"besuchen","en":"to attend, to visit","pos":"verb","example":"Meine Tochter besucht dreimal pro Woche einen Englischkurs.","exampleEn":"My daughter attends an English course three times a week.","note":"Perfekt: hat besucht."},{"id":"thema_essen_speisekarte","de":"die Speisekarte","en":"the menu","pos":"noun","example":"Der Kellner brachte uns sofort die Speisekarte und die Getränkekarte.","exampleEn":"The waiter immediately brought us the menu and the drinks menu.","note":"Plural: die Speisekarten."},{"id":"thema_essen_gericht","de":"das Gericht","en":"the dish, the meal","pos":"noun","example":"Das Gericht mit Fisch und Reis hat sehr gut geschmeckt.","exampleEn":"The dish with fish and rice tasted very good.","note":"Plural: die Gerichte."},{"id":"thema_essen_bestellen","de":"bestellen","en":"to order","pos":"verb","example":"Wir bestellen heute Abend eine Pizza und einen Salat.","exampleEn":"Tonight we are ordering a pizza and a salad.","note":"Perfekt: hat bestellt."},{"id":"thema_essen_zutat","de":"die Zutat","en":"the ingredient","pos":"noun","example":"Für dieses Rezept braucht man nur wenige frische Zutaten.","exampleEn":"For this recipe you need only a few fresh ingredients.","note":"Plural: die Zutaten. Meist im Plural verwendet."},{"id":"thema_essen_mitnehmen","de":"mitnehmen","en":"to take away, to take with you","pos":"verb","example":"Ich möchte das Essen bitte mitnehmen, wir haben es eilig.","exampleEn":"I would like to take the food with me, please, we are in a hurry.","note":"Perfekt: hat mitgenommen. Trennbares Verb: ich nehme mit."},{"id":"thema_essen_mahlzeit","de":"die Mahlzeit","en":"the meal","pos":"noun","example":"Die gemeinsame Mahlzeit am Abend ist für uns sehr wichtig.","exampleEn":"The shared meal in the evening is very important for us.","note":"Plural: die Mahlzeiten."},{"id":"thema_essen_fruehstueck","de":"das Frühstück","en":"the breakfast","pos":"noun","example":"Im Hotel war das Frühstück im Preis schon enthalten.","exampleEn":"In the hotel breakfast was already included in the price.","note":"Plural: die Frühstücke."},{"id":"thema_essen_rechnung","de":"die Rechnung","en":"the bill, the invoice","pos":"noun","example":"Der Kellner bringt am Ende die Rechnung an den Tisch.","exampleEn":"At the end the waiter brings the bill to the table.","note":"Plural: die Rechnungen."},{"id":"thema_essen_probieren","de":"probieren","en":"to try, to taste","pos":"verb","example":"Möchtest du den Kuchen einmal probieren? Er ist selbst gebacken.","exampleEn":"Would you like to try the cake? It is home-made.","note":"Perfekt: hat probiert."},{"id":"thema_essen_kellner","de":"der Kellner","en":"the waiter","pos":"noun","example":"Der Kellner hat uns freundlich zu einem freien Tisch begleitet.","exampleEn":"The waiter kindly accompanied us to a free table.","note":"Plural: die Kellner. Weibliche Form: die Kellnerin."},{"id":"thema_essen_getraenk","de":"das Getränk","en":"the drink, the beverage","pos":"noun","example":"Als Getränk nehme ich lieber Wasser als Cola.","exampleEn":"As a drink I prefer water to cola.","note":"Plural: die Getränke."},{"id":"thema_essen_schmecken","de":"schmecken","en":"to taste","pos":"verb","example":"Die Suppe schmeckt nach Knoblauch und frischen Kräutern.","exampleEn":"The soup tastes of garlic and fresh herbs.","note":"Perfekt: hat geschmeckt. Oft: Das schmeckt mir gut."}]}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.rule-1-die', 0, 'gender_rule', 'Endungen: immer feminin', 'Endings: always feminine', 'Diese Endungen sind sehr zuverlässig: Fast alle Nomen mit -ung, -heit, -keit, -schaft, -tion, -tät, -ie, -ei und -in sind feminin.', 'These endings are very reliable: almost all nouns in -ung, -heit, -keit, -schaft, -tion, -tät, -ie, -ei and -in are feminine.', '{"gender":"die","kind":"Endung","items":["-ung","-heit","-keit","-schaft","-tion","-tät","-ie","-ei","-in (weibliche Personen)"],"examples":[{"de":"die Wohnung","en":"flat","plural":"die Wohnungen"},{"de":"die Freiheit","en":"freedom","plural":"die Freiheiten"},{"de":"die Möglichkeit","en":"possibility","plural":"die Möglichkeiten"},{"de":"die Freundschaft","en":"friendship","plural":"die Freundschaften"}]}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.rule-2-der', 1, 'gender_rule', 'Endungen: immer maskulin', 'Endings: always masculine', 'Die Endungen -ling, -or, -ismus, -ant, -ent und -ist sind fast immer maskulin; bei -er gibt es aber Ausnahmen wie das Fenster und das Messer.', 'The endings -ling, -or, -ismus, -ant, -ent and -ist are almost always masculine; with -er there are exceptions such as das Fenster and das Messer.', '{"gender":"der","kind":"Endung","items":["-er (Personen und Geräte)","-ling","-or","-ismus","-ant","-ent","-ist"],"examples":[{"de":"der Lehrer","en":"teacher","plural":"die Lehrer"},{"de":"der Frühling","en":"spring","plural":"die Frühlinge"},{"de":"der Motor","en":"engine","plural":"die Motoren"},{"de":"der Praktikant","en":"intern","plural":"die Praktikanten"}]}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.rule-3-das', 2, 'gender_rule', 'Endungen: immer neutrum', 'Endings: always neuter', 'Die Verkleinerungsendungen -chen und -lein sind die sichersten Regeln im Deutschen; -nis kann auch feminin sein (die Kenntnis), und bei -tum gibt es der Reichtum.', 'The diminutive endings -chen and -lein are the most reliable rules in German; -nis can also be feminine (die Kenntnis), and -tum has der Reichtum.', '{"gender":"das","kind":"Endung","items":["-chen","-lein","-ment","-um","-nis","-tum","-ett"],"examples":[{"de":"das Brötchen","en":"bread roll","plural":"die Brötchen"},{"de":"das Büchlein","en":"little book","plural":"die Büchlein"},{"de":"das Dokument","en":"document","plural":"die Dokumente"},{"de":"das Museum","en":"museum","plural":"die Museen"}]}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.rule-4-der', 3, 'gender_rule', 'Bedeutungsgruppen: maskulin', 'Meaning groups: masculine', 'Diese Bedeutungsgruppen stimmen meistens, aber nicht immer: Es heißt der Wein, doch das Bier.', 'These meaning groups usually hold, but not always: it is der Wein, yet das Bier.', '{"gender":"der","kind":"Bedeutung","items":["Tage, Monate und Jahreszeiten","Wetter: Regen, Schnee, Wind, Nebel","alkoholische Getränke: Wein, Schnaps, Whisky","Autos und Motorräder: BMW, Harley","Züge und deren Namen"],"examples":[{"de":"der Montag","en":"Monday","plural":"die Montage"},{"de":"der Sommer","en":"summer","plural":"die Sommer"},{"de":"der Wein","en":"wine","plural":"die Weine"},{"de":"der BMW","en":"BMW (car)","plural":"die BMWs"}]}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.rule-5-die', 4, 'gender_rule', 'Bedeutungsgruppen: feminin', 'Meaning groups: feminine', 'Bei Zahlen, Bäumen und Blumen ist die Regel recht sicher, bei Flüssen und Schiffen gibt es jedoch viele Ausnahmen wie der Rhein und der Main.', 'With numbers, trees and flowers the rule is fairly safe, but with rivers and ships there are many exceptions such as der Rhein and der Main.', '{"gender":"die","kind":"Bedeutung","items":["Zahlen als Nomen: die Eins, die Zwei","Bäume und Blumen: die Eiche, die Rose","Flüsse in Deutschland: die Elbe, die Donau","Schiffe und Flugzeuge: die Titanic"],"examples":[{"de":"die Eins","en":"one (the number)","plural":"die Einsen"},{"de":"die Eiche","en":"oak","plural":"die Eichen"},{"de":"die Rose","en":"rose","plural":"die Rosen"},{"de":"die Boeing","en":"Boeing (plane)","plural":"die Boeings"}]}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.rule-6-das', 5, 'gender_rule', 'Bedeutungsgruppen: neutrum', 'Meaning groups: neuter', 'Metalle sind meistens neutrum, aber es heißt der Stahl und die Bronze; bei Ländern und Städten steht oft gar kein Artikel.', 'Metals are mostly neuter, but it is der Stahl and die Bronze; with countries and cities there is often no article at all.', '{"gender":"das","kind":"Bedeutung","items":["junge Lebewesen: das Baby, das Kalb, das Lamm","Metalle: das Eisen, das Gold, das Silber","Länder und Städte: das schöne Wien, das moderne Berlin","substantivierte Verben und Adjektive: das Essen, das Schöne"],"examples":[{"de":"das Metall","en":"metal","plural":"die Metalle"},{"de":"das Edelmetall","en":"precious metal","plural":"die Edelmetalle"},{"de":"das Essen","en":"meal, food","plural":"die Essen"},{"de":"das Junge","en":"young animal","plural":"die Jungen"}]}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-maedchen', 6, 'exception', 'das Mädchen', NULL, 'Die Endung -chen macht jedes Wort neutrum, auch wenn es eine weibliche Person bezeichnet.', 'The ending -chen makes any word neuter, even when it refers to a female person.', '{"en":"girl","plural":"die Mädchen","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-fraeulein', 7, 'exception', 'das Fräulein', NULL, 'Die Verkleinerungsendung -lein steht immer mit das, auch wenn das Wort eine weibliche Person meint.', 'The diminutive ending -lein always takes das, even when the word refers to a female person.', '{"en":"young lady","plural":"die Fräulein","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-baby', 8, 'exception', 'das Baby', NULL, 'Bei jungen Lebewesen entscheidet nicht das Geschlecht, sondern die Bedeutung: darum heißt es das Baby.', 'With young creatures it is not biological sex that decides but the meaning: hence das Baby.', '{"en":"baby","plural":"die Babys","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-kind', 9, 'exception', 'das Kind', NULL, 'Das Wort bezeichnet einen Menschen ohne festes Geschlecht, und solche Wörter sind im Deutschen neutrum.', 'The word refers to a person without a fixed sex, and such words are neuter in German.', '{"en":"child","plural":"die Kinder","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-weib', 10, 'exception', 'das Weib', NULL, 'Obwohl das Wort eine erwachsene Frau bezeichnet, ist es neutrum: das Weib, die Weiber.', 'Although the word refers to an adult woman, it is neuter: das Weib, die Weiber.', '{"en":"woman (pejorative)","plural":"die Weiber","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-kalb', 11, 'exception', 'das Kalb', NULL, 'Junge Tiere sind im Deutschen neutrum, auch wenn das Geschlecht des Tieres bekannt ist.', 'Young animals are neuter in German even when the animal''s sex is known.', '{"en":"calf","plural":"die Kälber","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-lamm', 12, 'exception', 'das Lamm', NULL, 'Die Bedeutung junges Tier ist stärker als jede Endungsregel: darum heißt es das Lamm.', 'The meaning ''young animal'' is stronger than any ending rule: hence das Lamm.', '{"en":"lamb","plural":"die Lämmer","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-fohlen', 13, 'exception', 'das Fohlen', NULL, 'Alle jungen Tiere stehen im Neutrum, deshalb heißt es das Fohlen und nicht der Fohlen.', 'All young animals are neuter, so it is das Fohlen and not der Fohlen.', '{"en":"foal","plural":"die Fohlen","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-kueken', 14, 'exception', 'das Küken', NULL, 'Junge Lebewesen sind neutrum, und das Küken bleibt im Plural unverändert: die Küken.', 'Young creatures are neuter, and das Küken stays unchanged in the plural: die Küken.', '{"en":"chick","plural":"die Küken","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-rind', 15, 'exception', 'das Rind', NULL, 'Das Rind ist der Oberbegriff für Kuh und Stier, und Oberbegriffe für Tiere sind oft neutrum.', 'das Rind is the collective term for cow and bull, and collective terms for animals are often neuter.', '{"en":"cattle, cow","plural":"die Rinder","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-schaf', 16, 'exception', 'das Schaf', NULL, 'Obwohl jedes Schaf ein Geschlecht hat, nennt das Wort beide Geschlechter, und darum steht das.', 'Although every sheep has a sex, the word covers both, and so it takes das.', '{"en":"sheep","plural":"die Schafe","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-junge', 17, 'exception', 'der Junge', NULL, 'Die Endung -e täuscht: der Junge ist maskulin und gehört zu den schwachen Nomen (den Jungen).', 'The ending -e is misleading here: der Junge is masculine and belongs to the weak nouns (den Jungen).', '{"en":"boy","plural":"die Jungen","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-name', 18, 'exception', 'der Name', NULL, 'Nomen der n-Deklination sind maskulin, auch wenn sie auf -e enden: der Name, den Namen.', 'Nouns of the n-declension are masculine even when they end in -e: der Name, den Namen.', '{"en":"name","plural":"die Namen","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-kaese', 19, 'exception', 'der Käse', NULL, 'Nicht jedes Wort auf -e ist feminin: der Käse ist maskulin und heißt im Plural die Käse.', 'Not every word in -e is feminine: der Käse is masculine and its plural is die Käse.', '{"en":"cheese","plural":"die Käse","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-frieden', 20, 'exception', 'der Frieden', NULL, 'Die Endung -en ist hier kein Femininum: der Frieden ist maskulin, auch wenn der Plural selten ist.', 'The ending -en is not feminine here: der Frieden is masculine, even though the plural is rare.', '{"en":"peace","plural":"die Frieden","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-glaube', 21, 'exception', 'der Glaube', NULL, 'Der Glaube gehört zur n-Deklination und ist maskulin: der Glaube, den Glauben.', 'der Glaube belongs to the n-declension and is masculine: der Glaube, den Glauben.', '{"en":"faith, belief","plural":"die Glauben","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-wille', 22, 'exception', 'der Wille', NULL, 'Der Wille ist maskulin und schwach: der Wille, den Willen, die Willen.', 'der Wille is masculine and weak: der Wille, den Willen, die Willen.', '{"en":"will","plural":"die Willen","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-funke', 23, 'exception', 'der Funke', NULL, 'Trotz der Endung -e ist der Funke maskulin: der Funke, den Funken, die Funken.', 'Despite the ending -e, der Funke is masculine: der Funke, den Funken, die Funken.', '{"en":"spark","plural":"die Funken","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-buchstabe', 24, 'exception', 'der Buchstabe', NULL, 'Der Buchstabe ist maskulin und schwach: der Buchstabe, den Buchstaben, die Buchstaben.', 'der Buchstabe is masculine and weak: der Buchstabe, den Buchstaben, die Buchstaben.', '{"en":"letter (of alphabet)","plural":"die Buchstaben","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-gedanke', 25, 'exception', 'der Gedanke', NULL, 'Die Endung -e macht den Gedanken nicht feminin: der Gedanke, den Gedanken, die Gedanken.', 'The ending -e does not make der Gedanke feminine: der Gedanke, den Gedanken, die Gedanken.', '{"en":"thought","plural":"die Gedanken","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-same', 26, 'exception', 'der Same', NULL, 'Der Same ist maskulin und gehört zur n-Deklination: der Same, den Samen, die Samen.', 'der Same is masculine and belongs to the n-declension: der Same, den Samen, die Samen.', '{"en":"seed","plural":"die Samen","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-herr', 27, 'exception', 'der Herr', NULL, 'Der Artikel stimmt, aber der Herr ist schwach: der Herr, den Herrn, dem Herrn, die Herren.', 'The article is right, but der Herr is weak: der Herr, den Herrn, dem Herrn, die Herren.', '{"en":"gentleman, Mr","plural":"die Herren","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-nachbar', 28, 'exception', 'der Nachbar', NULL, 'Der Nachbar ist maskulin und schwach: der Nachbar, den Nachbarn, die Nachbarn.', 'der Nachbar is masculine and weak: der Nachbar, den Nachbarn, die Nachbarn.', '{"en":"neighbour","plural":"die Nachbarn","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-kollege', 29, 'exception', 'der Kollege', NULL, 'Die Endung -e bedeutet hier kein Femininum: der Kollege, den Kollegen, die Kollegen.', 'The ending -e does not mean feminine here: der Kollege, den Kollegen, die Kollegen.', '{"en":"colleague","plural":"die Kollegen","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-kunde', 30, 'exception', 'der Kunde', NULL, 'Der Kunde ist maskulin und schwach, obwohl das Wort auf -e endet: den Kunden, die Kunden.', 'der Kunde is masculine and weak even though the word ends in -e: den Kunden, die Kunden.', '{"en":"customer","plural":"die Kunden","looks":"die"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-mensch', 31, 'exception', 'der Mensch', NULL, 'Wörter für Personen sind nicht automatisch neutrum: der Mensch, den Menschen, die Menschen.', 'Words for people are not automatically neuter: der Mensch, den Menschen, die Menschen.', '{"en":"human being","plural":"die Menschen","looks":"das"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-student', 32, 'exception', 'der Student', NULL, 'Die Endung -ent ist maskulin, aber der Student ist schwach: der Student, den Studenten.', 'The ending -ent is masculine, but der Student is weak: der Student, den Studenten.', '{"en":"student","plural":"die Studenten","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-die-butter', 33, 'exception', 'die Butter', NULL, 'Butter ist feminin, obwohl viele Speisen anders klingen, und das Wort hat keinen Plural: die Butter.', 'Butter is feminine even though many foods sound different, and the word has no plural: die Butter.', '{"en":"butter","plural":"kein Plural","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-die-milch', 34, 'exception', 'die Milch', NULL, 'Milch ist feminin, obwohl die meisten Getränke wie das Wasser neutrum sind: die Milch.', 'Milch is feminine even though most drinks, like das Wasser, are neuter: die Milch.', '{"en":"milk","plural":"kein Plural","looks":"das"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-die-wurst', 35, 'exception', 'die Wurst', NULL, 'Wurst ist feminin, obwohl viele Lebensmittel neutrum sind: die Wurst, die Würste.', 'Wurst is feminine even though many foods are neuter: die Wurst, die Würste.', '{"en":"sausage","plural":"die Würste","looks":"das"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-brot', 36, 'exception', 'das Brot', NULL, 'Anders als der Käse ist das Brot neutrum: das Brot, die Brote.', 'Unlike der Käse, das Brot is neuter: das Brot, die Brote.', '{"en":"bread","plural":"die Brote","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-ei', 37, 'exception', 'das Ei', NULL, 'Ei ist neutrum und bildet den Plural auf -er: das Ei, die Eier.', 'Ei is neuter and forms its plural in -er: das Ei, die Eier.', '{"en":"egg","plural":"die Eier","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-kaffee', 38, 'exception', 'der Kaffee', NULL, 'Kaffee ist maskulin, obwohl viele Getränke wie das Wasser neutrum sind: der Kaffee.', 'Kaffee is masculine even though many drinks, like das Wasser, are neuter: der Kaffee.', '{"en":"coffee","plural":"die Kaffees","looks":"das"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-tee', 39, 'exception', 'der Tee', NULL, 'Tee ist maskulin: der Tee, die Tees; nur wenige Getränke sind neutrum.', 'Tee is masculine: der Tee, die Tees; only a few drinks are neuter.', '{"en":"tea","plural":"die Tees","looks":"das"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-fenster', 40, 'exception', 'das Fenster', NULL, 'Die Endung -er ist meist maskulin, aber das Fenster ist neutrum: das Fenster, die Fenster.', 'The ending -er is usually masculine, but das Fenster is neuter: das Fenster, die Fenster.', '{"en":"window","plural":"die Fenster","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-zimmer', 41, 'exception', 'das Zimmer', NULL, 'Zimmer ist neutrum, obwohl die Endung -er oft maskuline Nomen kennzeichnet: die Zimmer.', 'Zimmer is neuter even though the ending -er often marks masculine nouns: die Zimmer.', '{"en":"room","plural":"die Zimmer","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-messer', 42, 'exception', 'das Messer', NULL, 'Messer ist neutrum, obwohl viele Werkzeuge auf -er maskulin sind: das Messer, die Messer.', 'Messer is neuter even though many tools in -er are masculine: das Messer, die Messer.', '{"en":"knife","plural":"die Messer","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-regal', 43, 'exception', 'das Regal', NULL, 'Regal ist neutrum und wird im Plural zu die Regale, auch wenn es wie ein maskulines Wort aussieht.', 'Regal is neuter and becomes die Regale in the plural, even though it looks like a masculine word.', '{"en":"shelf","plural":"die Regale","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-der-spiegel', 44, 'exception', 'der Spiegel', NULL, 'Nicht alle Wörter auf -el sind neutrum: der Spiegel ist maskulin und heißt im Plural die Spiegel.', 'Not all words in -el are neuter: der Spiegel is masculine and its plural is die Spiegel.', '{"en":"mirror","plural":"die Spiegel","looks":"das"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.exception-das-dach', 45, 'exception', 'das Dach', NULL, 'Dach ist neutrum und bildet den Plural mit Umlaut: das Dach, die Dächer.', 'Dach is neuter and forms its plural with an umlaut: das Dach, die Dächer.', '{"en":"roof","plural":"die Dächer","looks":"der"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-see', 46, 'double_gender', 'der See', NULL, 'Der Artikel ändert die Bedeutung: der See ist ein Binnensee, die See ist das Meer.', 'The article changes the meaning: der See is an inland lake, die See is the sea.', '{"en":"lake","other":"die See","otherEn":"sea"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-band', 47, 'double_gender', 'der Band', NULL, 'der Band ist ein Buch (die Bände), die Band ist eine Musikgruppe (die Bands).', 'der Band is a book (die Bände), die Band is a music group (die Bands).', '{"en":"volume (book)","other":"die Band","otherEn":"band (music group)"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-leiter', 48, 'double_gender', 'der Leiter', NULL, 'der Leiter ist eine Person, die etwas leitet; die Leiter ist ein Gerät zum Steigen.', 'der Leiter is a person who leads something; die Leiter is a ladder.', '{"en":"leader","other":"die Leiter","otherEn":"ladder"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-tor', 49, 'double_gender', 'der Tor', NULL, 'der Tor bedeutet Narr, das Tor bedeutet Tür oder Treffer im Sport.', 'der Tor means fool, das Tor means gate or a goal in sport.', '{"en":"fool","other":"das Tor","otherEn":"gate, goal"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-moment', 50, 'double_gender', 'der Moment', NULL, 'der Moment ist ein Augenblick, das Moment ist ein ausschlaggebender Umstand.', 'der Moment is a moment in time, das Moment is a decisive factor.', '{"en":"moment (in time)","other":"das Moment","otherEn":"factor, element"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-kiefer', 51, 'double_gender', 'der Kiefer', NULL, 'der Kiefer ist der Knochen im Kopf, die Kiefer ist ein Nadelbaum.', 'der Kiefer is the jawbone, die Kiefer is a pine tree.', '{"en":"jaw","other":"die Kiefer","otherEn":"pine (tree)"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-verdienst', 52, 'double_gender', 'der Verdienst', NULL, 'der Verdienst ist das verdiente Geld, das Verdienst ist eine anerkannte Leistung.', 'der Verdienst is the money you earn, das Verdienst is a recognised achievement.', '{"en":"earnings","other":"das Verdienst","otherEn":"merit"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-gehalt', 53, 'double_gender', 'der Gehalt', NULL, 'der Gehalt ist der Inhalt oder Anteil, das Gehalt ist der Lohn für die Arbeit.', 'der Gehalt is the content or proportion, das Gehalt is the salary.', '{"en":"content, proportion","other":"das Gehalt","otherEn":"salary"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-die-steuer', 54, 'double_gender', 'die Steuer', NULL, 'die Steuer ist Geld, das man an den Staat zahlt; das Steuer ist das Lenkrad.', 'die Steuer is money paid to the state; das Steuer is the steering wheel.', '{"en":"tax","other":"das Steuer","otherEn":"steering wheel"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-otter', 55, 'double_gender', 'der Otter', NULL, 'der Otter ist ein Säugetier im Wasser, die Otter ist eine Schlange.', 'der Otter is a mammal living in water, die Otter is a snake.', '{"en":"otter","other":"die Otter","otherEn":"viper (snake)"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-bauer', 56, 'double_gender', 'der Bauer', NULL, 'der Bauer ist ein Landwirt, das Bauer ist ein Käfig für Vögel.', 'der Bauer is a farmer, das Bauer is a birdcage.', '{"en":"farmer","other":"das Bauer","otherEn":"birdcage"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-golf', 57, 'double_gender', 'der Golf', NULL, 'der Golf ist ein Meerbusen, das Golf ist die Sportart mit Schläger und Ball.', 'der Golf is a gulf or bay, das Golf is the sport played with clubs and a ball.', '{"en":"gulf, bay","other":"das Golf","otherEn":"golf (sport)"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-kunde', 58, 'double_gender', 'der Kunde', NULL, 'der Kunde ist eine Person, die etwas kauft; die Kunde ist eine Nachricht.', 'der Kunde is a person who buys something; die Kunde is a piece of news.', '{"en":"customer","other":"die Kunde","otherEn":"news, message"}'::jsonb),
    ('gender-rules', 'telc-deutsch-b1.gender-rules.double-der-junge', 59, 'double_gender', 'der Junge', NULL, 'der Junge ist ein männliches Kind, das Junge ist ein Tierkind.', 'der Junge is a boy, das Junge is a young animal.', '{"en":"boy","other":"das Junge","otherEn":"young animal"}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.bestimmter-artikel', 0, 'table', 'Bestimmter Artikel: der / die / das', 'Definite article: der / die / das', 'Diese Tabelle brauchst du, wenn du über etwas Bestimmtes sprichst und der Artikel schon bekannt ist.', 'You need this table when you are talking about something specific and the article is already known.', '{"headers":["","maskulin","neutrum","feminin","Plural"],"headersEn":["","masculine","neuter","feminine","plural"],"rows":[["Nominativ","der","das","die","die"],["Akkusativ","den","das","die","die"],["Dativ","dem","dem","der","den (+ -n am Nomen)"],["Genitiv","des (+ -s)","des (+ -s)","der","der"]],"note":"Nur wenige Zellen ändern sich wirklich: maskulin wird im Akkusativ zu den und im Genitiv zu des, und im Dativ Plural steht den mit einem -n am Nomen.","noteEn":"Only a few cells really change: masculine becomes den in the accusative and des in the genitive, and in the dative plural it is den with an -n on the noun."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.unbestimmter-artikel', 1, 'table', 'Unbestimmter Artikel und ein-Wörter', 'Indefinite article and the ein-words', 'Diese Tabelle brauchst du, wenn du über etwas Unbestimmtes sprichst oder etwas verneinst oder besitzt.', 'You need this table when you are talking about something indefinite, or negating or owning something.', '{"headers":["","maskulin","neutrum","feminin","Plural"],"headersEn":["","masculine","neuter","feminine","plural"],"rows":[["Nominativ","ein","ein","eine","keine"],["Akkusativ","einen","ein","eine","keine"],["Dativ","einem","einem","einer","keinen"],["Genitiv","eines","eines","einer","keiner"]],"note":"kein- und die Possessivartikel mein-, dein-, sein-, ihr-, unser-, euer-, Ihr- haben genau dieselben Endungen wie ein-.","noteEn":"kein- and the possessive articles mein-, dein-, sein-, ihr-, unser-, euer-, Ihr- take exactly the same endings as ein-."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.personalpronomen', 2, 'table', 'Personalpronomen im Nominativ, Akkusativ und Dativ', 'Personal pronouns in the nominative, accusative and dative', 'Diese Tabelle brauchst du, wenn du eine Person nicht mit einem Nomen, sondern mit einem Pronomen nennst.', 'You need this table when you refer to a person with a pronoun instead of a noun.', '{"headers":["","Nominativ","Akkusativ","Dativ"],"headersEn":["","nominative","accusative","dative"],"rows":[["ich","ich","mich","mir"],["du","du","dich","dir"],["er","er","ihn","ihm"],["es","es","es","ihm"],["sie","sie","sie","ihr"],["wir","wir","uns","uns"],["ihr","ihr","euch","euch"],["sie","sie","sie","ihnen"],["Sie","Sie","Sie","Ihnen"]],"note":"Achte auf die Formen ihn/ihm, sie/ihr und sie/ihnen: Hier ändert sich das Pronomen stark, obwohl das Nomen gleich bleibt.","noteEn":"Watch the pairs ihn/ihm, sie/ihr and sie/ihnen: the pronoun changes a lot here even though the noun stays the same."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.fragewoerter', 3, 'table', 'Welcher Fall? Die Fragewörter', 'Which case? The question words', 'Diese Tabelle brauchst du, wenn du den Fall im Satz schnell bestimmen willst.', 'You need this table when you want to work out the case in a sentence quickly.', '{"headers":["Fall","Fragewort","Rolle im Satz","Beispiel"],"headersEn":["case","question word","role in the sentence","example"],"rows":[["Nominativ","Wer? Was?","das Subjekt","Der Kurs beginnt um neun."],["Akkusativ","Wen? Was?","das direkte Objekt","Ich kaufe den Kurs."],["Dativ","Wem?","das indirekte Objekt","Ich danke dem Lehrer."],["Genitiv","Wessen?","der Besitz","Das Auto meines Bruders ist neu."]],"note":"Stelle die Frage mit dem Fragewort und du hörst den Fall: Wer? für den Nominativ, Wen? für den Akkusativ und Wem? für den Dativ.","noteEn":"Ask the question with the question word and you will hear the case: Wer? for the nominative, Wen? for the accusative and Wem? for the dative."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.adjektivendungen-bestimmt', 4, 'table', 'Adjektivendungen nach der / die / das', 'Adjective endings after der / die / das', 'Diese Tabelle brauchst du, wenn ein Adjektiv nach dem bestimmten Artikel steht.', 'You need this table when an adjective comes after the definite article.', '{"headers":["","maskulin","neutrum","feminin","Plural"],"headersEn":["","masculine","neuter","feminine","plural"],"rows":[["Nominativ","-e","-e","-e","-en"],["Akkusativ","-en","-e","-e","-en"],["Dativ","-en","-en","-en","-en"],["Genitiv","-en","-en","-en","-en"]],"note":"Nach der / die / das steht fast immer -e oder -en, nur der Nominativ und der Akkusativ im Singular zeigen -e.","noteEn":"After der / die / das the ending is almost always -e or -en; only the nominative and accusative singular show -e."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.adjektivendungen-unbestimmt', 5, 'table', 'Adjektivendungen nach ein / kein / mein', 'Adjective endings after ein / kein / mein', 'Diese Tabelle brauchst du, wenn ein Adjektiv nach ein, kein oder einem Possessivartikel steht.', 'You need this table when an adjective follows ein, kein or a possessive article.', '{"headers":["","maskulin","neutrum","feminin","Plural"],"headersEn":["","masculine","neuter","feminine","plural"],"rows":[["Nominativ","-er","-es","-e","-en"],["Akkusativ","-en","-es","-e","-en"],["Dativ","-en","-en","-en","-en"],["Genitiv","-en","-en","-en","-en"]],"note":"Nach ein / kein / mein trägt das Adjektiv im Nominativ die Endung, die der bestimmte Artikel hätte: -er für maskulin, -es für neutrum, -e für feminin.","noteEn":"After ein / kein / mein the adjective carries the ending the definite article would have had: -er for masculine, -es for neuter, -e for feminine."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.n-deklination', 6, 'table', 'n-Deklination: der Junge, den Jungen', 'n-declension: der Junge, den Jungen', 'Diese Tabelle brauchst du, wenn ein maskulines Nomen im Akkusativ, Dativ oder Genitiv ein -n bekommt.', 'You need this table when a masculine noun takes an -n in the accusative, dative or genitive.', '{"headers":["","Nominativ","Akkusativ","Dativ"],"headersEn":["","nominative","accusative","dative"],"rows":[["der Junge","der Junge","den Jungen","dem Jungen"],["der Name","der Name","den Namen","dem Namen"],["der Herr","der Herr","den Herrn","dem Herrn"],["der Nachbar","der Nachbar","den Nachbarn","dem Nachbarn"],["der Kollege","der Kollege","den Kollegen","dem Kollegen"],["der Student","der Student","den Studenten","dem Studenten"],["der Mensch","der Mensch","den Menschen","dem Menschen"]],"note":"Bei diesen Nomen bleibt nur der Nominativ ohne -n; im Akkusativ, Dativ und Genitiv steht immer die Endung -n oder -en.","noteEn":"With these nouns only the nominative stays without -n; in the accusative, dative and genitive the ending is always -n or -en."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.praepositionen-kasus', 7, 'table', 'Präpositionen und ihr Fall', 'Prepositions and their case', 'Diese Tabelle brauchst du, wenn du nach einer Präposition den richtigen Artikel wählen willst.', 'You need this table when you want to choose the right article after a preposition.', '{"headers":["Fall","Präpositionen","Beispiel"],"headersEn":["case","prepositions","example"],"rows":[["Dativ","aus, bei, mit, nach, seit, von, zu, gegenüber","Ich fahre mit dem Bus."],["Akkusativ","durch, für, gegen, ohne, um, bis, entlang","Das Geschenk ist für meinen Bruder."],["Wechsel","an, auf, in, über, unter, vor, hinter, neben, zwischen","Ich hänge das Bild an die Wand. / Das Bild hängt an der Wand."]],"note":"Die Wechselpräpositionen zeigen den Akkusativ bei einer Bewegung (Wohin?) und den Dativ bei einer Position (Wo?).","noteEn":"The two-way prepositions take the accusative for movement (Wohin?) and the dative for a position (Wo?)."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.trigger-1-nominativ', 8, 'trigger', 'Verben mit Nominativ', 'verbs that take the nominative', 'Mein Bruder ist Lehrer und bleibt in Berlin.', 'My brother is a teacher and stays in Berlin.', '{"case":"Nominativ","items":["sein","werden","bleiben","heißen"]}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.trigger-2-dativ', 9, 'trigger', 'Verben mit Dativ', 'verbs that take the dative', 'Ich helfe dir und danke dir.', 'I help you and thank you.', '{"case":"Dativ","items":["helfen","danken","gefallen","gehören","antworten","passen","schmecken","gratulieren","folgen","wehtun"]}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.trigger-3-akkusativ', 10, 'trigger', 'Verben mit Akkusativ', 'verbs that take the accusative', 'Ich habe einen Bruder und besuche ihn jeden Sonntag.', 'I have a brother and visit him every Sunday.', '{"case":"Akkusativ","items":["haben","sehen","kaufen","brauchen","besuchen","fragen","suchen","es gibt"]}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.trigger-4-dativ', 11, 'trigger', 'Höfliche Wendungen', 'polite expressions', 'Die Suppe schmeckt mir gut, aber der Termin passt mir leider nicht.', 'I like the soup, but unfortunately the appointment doesn''t suit me.', '{"case":"Dativ","items":["es gefällt mir","es tut mir leid","es passt mir","es schmeckt mir","es geht mir gut"]}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.example-1', 12, 'example', 'Der Mann kauft den Hund und gibt dem Kind den Ball.', NULL, 'der = Nominativ (Subjekt), den = Akkusativ (direktes Objekt), dem = Dativ (indirektes Objekt).', NULL, '{"en":"The man buys the dog and gives the child the ball."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.example-2', 13, 'example', 'Meine Nachbarin hilft dem alten Herrn jeden Morgen.', NULL, 'Das Verb helfen verlangt immer den Dativ: dem alten Herrn.', NULL, '{"en":"My neighbour helps the old gentleman every morning."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.example-3', 14, 'example', 'Wir warten ohne unseren Vater am Eingang.', NULL, 'Die Präposition ohne steht mit dem Akkusativ: unseren Vater.', NULL, '{"en":"We wait at the entrance without our father."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.example-4', 15, 'example', 'Nach dem Unterricht gehe ich mit meiner Freundin ins Café.', NULL, 'Die Präpositionen nach und mit stehen mit dem Dativ: dem Unterricht, meiner Freundin.', NULL, '{"en":"After class I go to the café with my friend."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.example-5', 16, 'example', 'Ich hänge das Bild an die Wand.', NULL, 'Wechselpräposition mit Richtung (Wohin?): an die Wand = Akkusativ.', NULL, '{"en":"I hang the picture on the wall."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.example-6', 17, 'example', 'Das Bild hängt an der Wand.', NULL, 'Wechselpräposition mit Position (Wo?): an der Wand = Dativ.', NULL, '{"en":"The picture hangs on the wall."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.example-7', 18, 'example', 'Ich sehe den Studenten und spreche mit dem Studenten.', NULL, 'n-Deklination: der Student bekommt im Akkusativ und im Dativ die Endung -en.', NULL, '{"en":"I see the student and speak with the student."}'::jsonb),
    ('cases-guide', 'telc-deutsch-b1.cases-guide.example-8', 19, 'example', 'Ich fahre mit meinem neuen Auto zu meiner Arbeit.', NULL, 'Possessivartikel im Dativ: mit meinem Auto, zu meiner Arbeit.', NULL, '{"en":"I drive to work with my new car."}'::jsonb)
